return ['domain'=>NULL,'plural-forms'=>'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','language'=>'hr','project-id-version'=>'TranslatePress Multilingual','pot-creation-date'=>'2026-10-13T10:48:01+03:00','po-revision-date'=>'2026-03-27 09:00:36+0000','x-generator'=>'TranslatePress build (community + OpenRouter), 2026-10-13','messages'=>['TranslatePress - DEV'=>'TranslatePress - DEV','https://translatepress.com/'=>'https://translatepress.com/','Experience a better way of translating your WordPress site using a visual front-end translation editor, with full support for WooCommerce and site builders.'=>'Doživite bolji način prevođenja svoje WordPress stranice pomoću vizualnog front-end uređivača prijevoda, s punom podrškom za WooCommerce i graditelje web stranica.','Cozmoslabs, Razvan Mocanu, Madalin Ungureanu, Cristophor Hurduban'=>'Cozmoslabs, Razvan Mocanu, Madalin Ungureanu, Cristophor Hurduban','https://cozmoslabs.com/'=>'https://cozmoslabs.com/','Active'=>'Aktivan','The inactive languages will still be visible and active for the admin. For other users they won\'t be visible in the language switchers and won\'t be accessible either.'=>'Neaktivni jezici i dalje će biti vidljivi i aktivni za administratora. Drugim korisnicima neće biti vidljivi u izmjenjivačima jezika niti će im biti dostupni.','unknown'=>'nepoznato','<strong>Extra Languages add-on</strong> requires TranslatePress version %1$s or higher. You are currently using version %2$s. Please update TranslatePress to enable this feature.'=>'<strong>Dodatak Extra Languages</strong> zahtijeva TranslatePress verziju %1$s ili noviju. Trenutno koristite verziju %2$s. Ažurirajte TranslatePress kako biste omogućili ovu značajku.','Dismiss this notice.'=>'Odbaci ovu obavijest.','Post Slug'=>'Slug objave','URL Slugs Translation'=>'Prijevod URL slugova','Slugs'=>'Slugovi','Taxonomy Slugs'=>'Razvrstavanje slugova','Search Taxonomy Slugs'=>'Pretraži razvrstavanje slugova','Taxonomy Slug'=>'Razvrstavanje sluga','Translation'=>'Prijevod','Term Slugs'=>'Pojam slugova','Search Term Slugs'=>'Pretraživanje pojma slugova','Term Slug'=>'Pojam slug','Taxonomy'=>'Razvrstavanje','Filter by Taxonomy'=>'Filtriraj prema razvrstavanju','Post Slugs'=>'Slugovi objave','Search Post Slugs'=>'Pretraži slugove objave','Post ID'=>'ID objave','Post Type'=>'Vrsta objave','Filter by Post Type'=>'Filtrirajte prema vrsti objave','Published'=>'Objavi','Any Post Status'=>'Bilo koji status objave','Post Type Base Slugs'=>'Vrsta objave osnovni slugovi','Post Type Base Slug'=>'Vrsta objave osnovni slug','Search Post Type Base Slugs'=>'Pretraži vrste objave osnovnh slugova','WooCommerce Slugs'=>'WooCommerce slugovi','WooCommerce Slug'=>'WooCommerce slug','Search WooCommerce Slugs'=>'Pretraži WooCommerce slugove','Automatic and manual slug translation changes performed when <strong>TranslatePress - Multilingual</strong> 2.8.4 was active had to be removed because of some issues with that version. All slug translations from before that version are now in use. Thank you for understanding!'=>'Automatske i ručne promjene prijevoda sluga izvršene kada je <strong>TranslatePress - Multilingual</strong> 2.8.4 bio aktivan morale su biti uklonjene zbog nekih problema s tom verzijom. Svi prijevodi slugova prije te verzije sada su u upotrebi. Hvala na razumijevanju!','If you absolutely need them, the removed translations can be found in tables trp_slug_original_obsolete and trp_slug_translation_obsolete.'=>'Ako su vam apsolutno potrebni, uklonjeni prijevodi mogu se naći u tablicama trp_slug_original_obsolete i trp_slug_translation_obsolete.','(inactive)'=>'(neaktivno)','Other Slugs'=>'Drugi slugovi','Search Other Slugs'=>'Pretraži druge slugove','Automatic User Language Detection'=>'Automatsko prepoznavanje korisničkog jezika','Invalid language code'=>'Nevažeći jezični kod','We\'ve detected you might be speaking a different language. Do you want to change to:'=>'Otkrili smo da možda govorite drugi jezik. Želite li se prebaciti na:','Change Language'=>'Promijeni jezik','Close and do not switch language'=>'Zatvori i ne mijenjaj jezik','First by browser language, then IP address (recommended)'=>'Prvo prema jeziku preglednika, zatim prema IP adresi (preporučeno)','First by IP address, then by browser language'=>'Prvo prema IP adresi, zatim prema jeziku preglednika','Only by browser language'=>'Samo prema jeziku preglednika','Only by IP address'=>'Samo prema IP adresi','A popup appears asking the user if they want to be redirected'=>'Pojavljuje se skočni prozor koji pita korisnika želi li biti preusmjeren','Redirect directly (*not recommended)'=>'Preusmjeri izravno (*ne preporučuje se)','Pop-up window over the content'=>'Skočni prozor iznad sadržaja','Hello bar before the content'=>'Hello traka prije sadržaja','Automatic User Language Detection requires a newer version of TranslatePress to use its visual settings interface. The legacy settings form will remain available until TranslatePress is updated.'=>'Automatsko prepoznavanje jezika korisnika zahtijeva noviju verziju TranslatePress za korištenje vizualnog sučelja postavki. Obrazac za naslijeđene postavke ostati će dostupan dok se TranslatePress ne ažurira.','Update TranslatePress'=>'Ažuriraj TranslatePress','WARNING. Cannot determine your language preference based on your current IP.<br>This is most likely because the website is on a local environment.'=>'UPOZORENJE. Ne mogu odrediti vaše postavke jezika na temelju vašeg trenutnog IP-a.<br>To je najvjerojatnije zato što je web stranica u lokalnom okruženju.','Permission denied.'=>'Dozvola je odbijena.','Invalid nonce.'=>'Nevažeći nonce.','Invalid settings.'=>'Nevažeće postavke.','Settings saved.'=>'Postavke su spremljene.','Go to <a href="%s" target="_self">Advanced</a> tab to change this feature\'s settings'=>'Idite na karticu <a href="%s" target="_self">Napredno</a> da biste promijenili postavke ove značajke','Website language selector'=>'Birač jezika web stranice','Change language'=>'Promijeni jezik','Available languages'=>'Dostupni jezici','Please enter your DeepL API key.'=>'Unesite svoj DeepL API ključ.','DeepL'=>'DeepL','Bad request. There was an error accessing the DeepL API.'=>'Loš zahtjev. Došlo je do pogreške prilikom pristupa DeepL API-ju.','The API key entered is invalid.'=>'Uneseni API ključ je nevažeći.','The API resource could not be found.'=>'Resurs API-ja nije pronađen.','The request size is too large.'=>'Veličina zahtjeva je prevelika.','The request is too long.'=>'Zahtjev je predug.','Too many requests. Please try again later.'=>'Previše zahtjeva. Pokušajte ponovno kasnije.','Your translation quota has been reached.'=>'Dosegnuta je vaša kvota prijevoda.','We could not process your request. Please try again later.'=>'Nismo mogli obraditi vaš zahtjev. Pokušajte ponovno kasnije.','There is an error on the DeepL service and your request could not be processed.'=>'Došlo je do pogreške na usluzi DeepL i vaš zahtjev nije mogao biti obrađen.','DeepL API Type'=>'Vrsta API-ja DeepL','Pro'=>'Pro','Free'=>'Besplatno','Select the type of DeepL API you want to use.'=>'Odaberite vrstu DeepL API-ja koji želite koristiti.','DeepL API Key'=>'DeepL API ključ','Visit <a href="%s" target="_blank">this link</a> to see how you can set up an API key and control API costs.'=>'Posjetite <a href="%s" target="_blank">ovu vezu</a> da biste vidjeli kako možete postaviti API ključ i kontrolirati troškove API-ja.','No Active License Detected for this website.'=>'Nije otkrivena aktivna licenca za ovu web stranicu.','Enter your license key'=>'Unesite vaš licencni ključ',' Or %1$spurchase one here%2$s'=>' Ili %1$s ga skupite ovdje%2$s','Different Domain per Language'=>'Različita domena po jeziku','View Docs'=>'Prikaz dokumenata','Assign different domains or subdomains to each language. When visitors access these domains, TranslatePress loads the appropriate language translation directly without redirecting.'=>'Dodijelite različite domene ili poddomene svakom jeziku. Kada posjetitelji pristupe tim domenama, TranslatePress učitava odgovarajući jezični prijevod izravno bez preusmjeravanja.','Example: %1$s for English, %2$s for Spanish, %3$s for French.'=>'Primjer: %1$s za engleski, %2$s za španjolski, %3$s za francuski.','Before enabling:'=>'Prije omogućavanja:','Ensure your domains are registered, pointed to your server, and have SSL certificates configured.'=>'Provjerite jesu li vaše domene registrirane, usmjerene na vaš server i imate konfigurirane SSL certifikate.','Domain'=>'Domena','Map this language to a different domain or sub-domain.'=>'Mapirajte ovaj jezik na drugu domenu ili poddomenu.','https://example.com'=>'https://example.com','Prefill with current domain'=>'Prethodno popuni s trenutnom domenom','Check DNS'=>'Provjeri DNS','Checking DNS...'=>'Provjeravam DNS...','DNS is correctly configured!'=>'DNS je ispravno konfiguriran!','DNS check failed. Please verify your domain configuration.'=>'DNS provjera nije uspjela. Molimo provjerite konfiguraciju svoje domene.','This domain is already assigned to another language.'=>'Ta domena je već dodijeljena drugom jeziku.','<strong>Different Domain per Language add-on</strong> requires TranslatePress version %1$s or higher. You are currently using version %2$s. Please update TranslatePress to enable this feature.'=>'<strong>Dodatak Different Domain per Language</strong> zahtijeva TranslatePress verziju %1$s ili noviju. Trenutno koristite verziju %2$s. Ažurirajte TranslatePress kako biste omogućili ovu značajku.','Note: This option is disabled when Different Domain for Language addon is active.'=>'Napomena: Ova opcija je onemogućena kada je dodatak Različita domena po jeziku aktivan.','Different Domain per Language: Domain is required when domain mapping is enabled. The toggle has been disabled for languages with empty domains.'=>'Različita domena po jeziku: Domena je potrebna kada je mapiranje domena omogućeno. Izmjenjivač je onemogućen za jezike s praznim domenama.','Different Domain per Language: The same domain cannot be assigned to multiple languages. The toggle has been disabled for duplicate domains.'=>'Različita domena po jeziku: Ista domena ne može se dodijeliti za više jezika. Izmjenjivač je onemogućen za duplicirane domene.','Different Domain per Language: A language domain cannot be the same as the main site URL. The toggle has been disabled for the matching domain.'=>'Različita domena po jeziku: Jezična domena ne može biti ista kao glavni URL stranice. Prekidač je onemogućen za domenu podudaranja.','Please enter a domain.'=>'Molimo unesite domenu.','Invalid domain format.'=>'Nevažeći format domene.','Could not reach domain: %s'=>'Nije se moglo doći do domene: %s','Domain is reachable!'=>'Domena je dostupna!','Domain returned HTTP status %d.'=>'Domena vraća HTTP status %d.','Limit this menu item to the following languages'=>'Ograničite ovu stavku izbornika na sljedeće jezike','All Languages'=>'Svi jezici','Translator'=>'Prevoditelj',' TranslatePress Settings'=>' TranslatePress Postavke','Allow this user to translate the website.'=>'Dopustite ovom korisniku da prevede web stranicu.','Translate Site'=>'Prevedi stranicu','Add-On'=>'Dodatak','Deactivate'=>'Deaktiviraj','Activate'=>'Aktiviraj','Installing...'=>'Instaliram...','This add-on can not be activated back without a valid license. Are you sure you want to deactivate it?'=>'Ovaj dodatak se ne može ponovno aktivirati bez valjane licence. Jeste li sigurni da ga želite deaktivirati?','Documentation'=>'Dokumentacija','A valid license is required to activate add-ons.'=>'Za aktivaciju dodataka potrebna je važeća licenca.','Activate all'=>'Aktiviraj sve','Add-ons can not be activated back without a valid license. Are you sure you want to deactivate them?'=>'Dodaci se ne mogu ponovno aktivirati bez valjane licence. Jeste li sigurni da ih želite deaktivirati?','Deactivate all'=>'Deaktiviraj sve','%1$sAdd-ons settings saved successfully%2$s'=>'%1$sPostavke dodataka uspješno su spremljene%2$s','Date format'=>'Format datuma','Customize the date formatting per each translated language.<br/>Leave empty for default WP setting or see more information <a href="https://wordpress.org/support/article/formatting-date-and-time/" title="Formatting Date and Time" target="_blank">here</a>'=>'Prilagodite oblikovanje datuma za svaki prevedeni jezik.<br/>Ostavite prazno za zadanu WP postavku ili pogledajte više informacija <a href="https://wordpress.org/support/article/formatting-date-and-time/" title="Formatiranje datuma i vremena" target="_blank">ovdje</a>','To edit an existing TranslatePress language, input the language code and fill in only the columns you want to overwrite (e.g. Language name, Flag).<br>You can also add new custom languages. They will be available under General settings, All Languages list, where the URL slug can be edited.'=>'Da biste uredili postojeći jezik TranslatePress, unesite kod jezika i ispunite samo stupce koje želite prebrisati (npr. Naziv jezika, Zastavica). <br>Možete dodati i nove prilagođene jezike. Bit će dostupni u odjeljku Opće postavke, Popis svih jezika, gdje se URL slug može uređivati.','For custom flag, first upload the image in media library then paste the URL.<br>Changing or deleting a custom language will impact translations and site URL\'s.<br>The Language code and the ISO Code should contain only alphabetical values, numerical values, "-" and "_".<br>The ISO Codes can be found on <a href = "https://cloud.google.com/translate/docs/languages" target = "_blank">Google ISO Codes</a> and <a href = "https://www.deepl.com/docs-api/translating-text/" target = "_blank">DeepL Target Codes</a>.'=>'Za prilagođenu zastavicu prvo prenesite sliku u medijsku biblioteku, a zatim zalijepite URL. <br>Promjena ili brisanje prilagođenog jezika utjecat će na prijevode i URL-ove web stranice. <br>Jezični kod i ISO kod trebaju sadržavati samo abecedne vrijednosti, numeričke vrijednosti, "-" i "_". <br>ISO kodovi mogu se pronaći na <a href = "https://cloud.google.com/translate/docs/languages" target = "_blank">Google ISO kodovi</a> i <a href = "https://www.deepl.com/docs-api/translating-text/" target = "_blank">DeepL ciljni kodovi</a>.','Language code'=>'Kod jezika','Language name'=>'Naziv jezika','Native name'=>'Izvorni naziv','ISO Code'=>'ISO kod','Flag URL'=>'URL zastavice','Text RTL'=>'Tekst RTL','Custom language'=>'Prilagođeni jezik','Disable bundled plugin translations'=>'Onemogući ugrađene prijevode dodatka','By default, TranslatePress ships its own translation files in <code>wp-content/plugins/translatepress/languages/</code> and forces WordPress to use them instead of the language packs installed automatically from translate.wordpress.org.<br/>Enable this option to disable that override. WordPress will then load the community language pack from <code>wp-content/languages/plugins/</code> (if present) and fall back to the bundled files only when no pack is available.'=>'Prema zadanim postavkama, TranslatePress isporučuje vlastite datoteke prijevoda u <code>wp-content/plugins/translatepress/languages/</code> i prisiljava WordPress da ih koristi umjesto jezičnih paketa automatski instaliranih s translate.wordpress.org.<br/>Omogućite ovu opciju da onemogućite to nadjačavanje. WordPress će tada učitati jezični paket zajednice iz <code>wp-content/languages/plugins/</code> (ako postoji) i koristiti ugrađene datoteke samo kada nijedan paket nije dostupan.','Disable dynamic translation'=>'Onemogući dinamički prijevod','It disables detection of strings displayed dynamically using JavaScript. <br/>Strings loaded via a server side AJAX call will still be translated.'=>'Onemogućuje otkrivanje nizova koji se dinamički prikazuju pomoću JavaScripta. <br/>Nizovi učitani putem AJAX poziva na strani poslužitelja i dalje će se prevoditi.','Disable translation for gettext strings'=>'Onemogućite prijevod za gettext nizove','Gettext Strings are strings outputted by themes and plugins. <br> Translating these types of strings through TranslatePress can be unnecessary if they are already translated using the .po/.mo translation file system.<br>Enabling this option can improve the page load performance of your site in certain cases. The disadvantage is that you can no longer edit gettext translations using TranslatePress, nor benefit from automatic translation on these strings.'=>'Gettext Strings su nizovi koje generiraju teme i dodaci. <br> Prevođenje ovih vrsta nizova putem TranslatePressa može biti nepotrebno ako su već prevedene pomoću .po/.mo datotečnog sustava za prijevod. <br>Omogućavanje ove opcije može poboljšati izvedbu učitavanja stranice vaše web-lokacije u određenim slučajevima. Nedostatak je što više ne možete uređivati prijevode gettexta pomoću TranslatePressa, niti imati koristi od automatskog prevođenja na tim nizovima.','Gettext Strings translation is disabled'=>'Prijevod Gettext Strings je onemogućen','To enable it go to '=>'Da biste ga omogućili, idite na ','TranslatePress->Advanced Settings->Debug->Disable translation for gettext strings'=>'TranslatePress->Napredne postavke->Otklanjanje pogrešaka->Onemogući prijevod za gettext nizove',' and uncheck the Checkbox.'=>' i poništite potvrdni okvir.','Dismiss'=>'Odbaci','Exclude translated links from sitemap'=>'Izuzimanje prevedenih veza s karte stranice','Do not include translated links in sitemaps generated by SEO plugins.<br/>Requires <a href="https://translatepress.com/docs/addons/seo-pack/?utm_source=tp-advanced&utm_medium=client-site&utm_campaign=miscellaneous" title="TranslatePress Add-on SEO Pack documentation" target="_blank"> SEO Pack Add-on</a> to be installed and activated.'=>'Nemojte uključivati prevedene poveznice u karte stranica koje generiraju SEO dodaci.<br/>Zahtijeva <a href="https://translatepress.com/docs/addons/seo-pack/?utm_source=tp-advanced&utm_medium=client-site&utm_campaign=miscellaneous" title="TranslatePress Add-on SEO Pack documentation" target="_blank"> instalaciju i aktivaciju</a> dodatka SEO Pack.','Disable post container tags for post title'=>'Onemogući oznake spremnika objava za naslov objave','It disables search indexing the post title in translated languages.<br/>Useful when the title of the post doesn\'t allow HTML thus breaking the page.'=>'Onemogućava indeksiranje pretraživanja naslova objave na prevedenim jezicima.<br/>Korisno kada naslov objave ne dopušta HTML i tako razbija stranicu.','Disable post container tags for post content'=>'Onemogući oznake spremnika objava za sadržaj objave','It disables search indexing the post content in translated languages.<br/>Useful when the content of the post doesn\'t allow HTML thus breaking the page.'=>'Onemogućava indeksiranje sadržaja objave pretraživanjem na prevedenim jezicima.<br/>Korisno kada sadržaj objave ne dopušta HTML i tako razbija stranicu.','Do not translate certain paths'=>'Nemojte prevoditi određene putanje','Choose what paths can be translated. Supports wildcard at the end of the path.<br>For example, to exclude https://example.com/some/path you can either use the rule /some/path/ or /some/*.<br>Enter each rule on it\'s own line. To exclude the home page use {{home}}.'=>'Odaberite koji se putovi mogu prevesti. Podržava zamjenski znak na kraju puta.<br>Na primjer, da biste https://example.com/some/path isključili, možete koristiti pravilo /some/path/ ili /some/*.<br>Unesite svako pravilo u vlastiti red. Da biste izuzeli početnu stranicu, upotrijebite {{home}}.','Exclude Paths From Translation'=>'Izuzimanje putova iz prijevoda','Translate Only Certain Paths'=>'Prevođenje samo određenih putova','Enable the hreflang x-default tag for language:'=>'Omogućite oznaku hreflang x-default za jezik:','Enables the hreflang="x-default" for an entire language. See documentation for more details.'=>'Omogućuje hreflang="x-default" za cijeli jezik. Za više detalja pogledajte dokumentaciju.','Translate numbers and numerals'=>'Prevedite brojeve i numeriranje','Enable translation of numbers ( e.g. phone numbers)'=>'Omogućite prijevod brojeva (npr. telefonskih brojeva)','Selector'=>'Izbornik','Exclude from dynamic translation'=>'Izuzimanje iz dinamičkog prevođenja','Do not dynamically translate strings that are found in html nodes matching these selectors.<br>Excludes all the children of HTML nodes matching these selectors from being translated using JavaScript.<br/>These strings will still be translated on the server side if possible.'=>'Nemojte dinamički prevoditi nizove koji se nalaze u html čvorovima koji odgovaraju tim biračima. <br>Isključuje sve potomke HTML čvorova koji odgovaraju ovim selektorima iz prevođenja pomoću JavaScripta.<br/>Ti će se nizovi i dalje prevoditi na strani poslužitelja ako je moguće.','Gettext String'=>'Gettext niz','Exclude Gettext Strings'=>'Izuzimanje nizova Gettext','Exclude these strings from being translated as Gettext strings by TranslatePress. Leave the domain empty to take into account any Gettext string.<br/>Can still be translated through po/mo files.'=>'Izuzmite ove nizove iz prijevoda kao Gettext nizove od strane TranslatePressa. Ostavite domenu praznu da biste uzeli u obzir bilo koji Gettext niz.<br/>I dalje se može prevesti putem po/mo datoteka.','Exclude selectors only from automatic translation'=>'Izuzimanje selektora samo iz automatskog prevođenja','Do not automatically translate strings that are found in html nodes matching these selectors.<br>Excludes all the children of HTML nodes matching these selectors from being automatically translated.<br>Manual translation of these strings is still possible.'=>'Nemojte automatski prevoditi nizove koji se nalaze u html čvorovima koji odgovaraju tim biračima. <br>Isključuje automatsko prevođenje svih podređenih HTML čvorova koji odgovaraju ovim selektorima. <br>Ručni prijevod ovih nizova još uvijek je moguć.','Exclude selectors from translation'=>'Izuzimanje selektora iz prijevoda','Do not translate strings that are found in html nodes matching these selectors.<br>Excludes all the children of HTML nodes matching these selectors from being translated.<br>These strings cannot be translated manually nor automatically.'=>'Nemojte prevoditi nizove koji se nalaze u html čvorovima koji odgovaraju ovim selektorima. <br>Isključuje sve potomke HTML čvorova koji odgovaraju ovim selektorima iz prijevoda. <br>Ti se nizovi ne mogu prevesti ni ručno ni automatski.','String'=>'Niz','Exclude strings from automatic translation'=>'Isključite nizove iz automatskog prijevoda','Do not automatically translate these strings (ex. names, technical words...)<br>Paragraphs containing these strings will still be translated except for the specified part.'=>'Nemojte automatski prevoditi ove nizove (npr. imena, tehničke riječi...)<br>Odlomci koji sadrže ove nizove i dalje će se prevoditi osim navedenog dijela.','Fix broken HTML'=>'Ispravite pokvareni HTML','General attempt to fix broken or missing HTML on translated pages.<br/>'=>'Općeniti pokušaj ispravljanja pokvarenog ili nedostajućeg HTML-a na prevedenim stranicama.<br/>','Force slash at end of home url:'=>'Prisilna kosa crta na kraju početnog URL-a:','Ads a slash at the end of the home_url() function'=>'Dodaj kosu crtu na kraju funkcije home_url()','Show Both (recommended)'=>'Prikaži oboje (preporučeno)','Remove Country Locale'=>'Ukloni regionalnu shemu države','Remove Region Independent Locale'=>'Ukloni regionalnu shemu neovisnu o regiji','Remove duplicate hreflang'=>'Uklanjanje dupliciranog hreflanga','Choose which hreflang tags will appear on your website.<br/>We recommend showing both types of hreflang tags as indicated by <a href="https://developers.google.com/search/docs/advanced/crawling/localized-versions" title="Google Crawling" target="_blank">Google documentation</a>.<br/>Removing Country Locale when having multiple Country Locales of the same language (ex. English UK and English US) will result in showing one hreflang tag with link to just one of the region locales for that language.'=>'Odaberite koje će se oznake hreflang prikazivati na vašoj web stranici.<br/>Preporučujemo da prikažete obje vrste oznaka hreflang kao što je navedeno u <a href="https://developers.google.com/search/docs/advanced/crawling/localized-versions" title="Google indeksiranje" target="_blank">Googleova dokumentacija</a>.<br/>Uklanjanje regionalne sheme države kada imate više regionalnih shema za istu zemlju (npr. engleski UK i engleski SAD) rezultirat će prikazivanjem jedne oznake hreflang s vezom na samo jednu regionalnu shemu regije za taj jezik.','Default (example: en-US, fr-CA, etc.)'=>'Zadano (primjer: en-US, fr-CA, itd.)','Regional (example: en, fr, es, etc.)'=>'Regionalni (primjer: en, fr, es, itd.)','HTML Lang Attribute Format'=>'Format atributa HTML lang','Change lang attribute of the html tag to a format that includes country regional or not. <br>In HTML, the lang attribute (<html lang="en-US">)  should be used to  specify the language of text content so that the  browser can correctly display or process  your content (eg. for  hyphenation, styling, spell checking, etc).'=>'Promijenite atribut lang html oznake u format koji uključuje regionalnu ili neregionalnu zemlju. <br>U HTML-u bi se atribut lang (<html lang="en-US">)  trebao koristiti za  određivanje jezika tekstualnog sadržaja kako bi  preglednik mogao ispravno prikazati ili obraditi  vaš sadržaj (npr. za  dijeljenje riječi, stiliziranje, provjeru pravopisa itd.).','Load legacy Language Switcher'=>'Učitavanje naslijeđenog izmjenjivača jezika','Applies to all types of language switchers (floating, shortcode, and menu). When enabled, the site will revert to using the original Language Switcher configured in the General Settings tab, replacing the new customizable version. Your existing switcher settings will remain saved, but they will be ignored while this option is active.'=>'Primjenjuje se na sve vrste izmjenjivača jezika (plutajući, kratki kod i izbornik). Kada je omogućeno, web-mjesto će se vratiti na korištenje izvornog izmjenjivača jezika konfiguriranog na kartici Opće postavke, zamjenjujući novu prilagodljivu verziju. Vaše postojeće postavke prebacivača ostat će spremljene, ali će se zanemariti dok je ova opcija aktivna.','Load legacy SEO Pack Add-On'=>'Učitajte naslijeđeni dodatak SEO paketa','In case the recent migration to the new slug rewrite is causing trouble, set this to Yes to use the old method <br> Please <a href="https://translatepress.com/support/open-ticket/?utm_source=tp-advanced&utm_medium=client-site&utm_campaign=troubleshooting" target="_blank">open a support ticket</a> letting us know of the issues you are having.'=>'U slučaju da nedavna migracija na novo prepisivanje slugova uzrokuje probleme, postavite ovo na Da da biste koristili staru metodu <br><a href="https://translatepress.com/support/open-ticket/?utm_source=tp-advanced&utm_medium=client-site&utm_campaign=troubleshooting" target="_blank">Otvorite zahtjev za podršku i obavijestite</a> nas o problemima koje imate.','Manual Translation Only'=>'Samo ručni prijevod','TranslatePress pro-actively scans and saves strings in the database when users access translated pages. <br>This setting disables this functionality and only allows translation and string saving when inside the Translation Editor. <br>Also disables machine translation outside the Translation Editor, giving you better control over character spending, by translating only the pages you visit in the Translation Editor.'=>'TranslatePress proaktivno skenira i sprema stringove u bazi podataka kada korisnici pristupaju prevedenim stranicama. <br>Ova postavka onemogućava ovu funkcionalnost i dopušta prijevod i spremanje nizova samo kada su unutar uređivača prijevoda. <br>Također onemogućava strojno prevođenje izvan uređivača prijevoda, dajući vam bolju kontrolu nad trošenjem znakova, tako da prevode samo stranice koje posjetite u uređivaču prijevoda.','Open language switcher only on click'=>'Otvori prekidač jezika samo na klik','Open the language switcher shortcode by clicking on it instead of hovering.<br> Close it by clicking on it, anywhere else on the screen or by pressing the escape key. This will affect only the shortcode language switcher.'=>'Otvorite kratki kod za promjenu jezika klikom na njega umjesto lebdenja. <br> Zatvorite ga klikom na njega, bilo gdje drugdje na zaslonu ili pritiskom na tipku za bijeg. To će utjecati samo na prekidač jezika kratkog koda.','Show opposite language in the language switcher'=>'Prikaz suprotnog jezika u izmjenjivaču jezika','Transforms the language switcher into a button showing the other available language, not the current one.<br> Only works when there are exactly two languages, the default one and a translation one.<br>This will affect the shortcode language switcher and floating language switcher as well.<br> To achieve this in menu language switcher go to Appearance->Menus->Language Switcher and select Opposite Language.'=>'Pretvara izmjenjivač jezika u gumb koji prikazuje drugi dostupni jezik, a ne trenutačni. <br> Radi samo kada postoje točno dva jezika, zadani i prijevodni. <br>To će utjecati i na prekidač jezika kratkog koda i promjenjivač plutajućeg jezika. <br> Da biste to postigli u izmjenjivaču jezika izbornika, idite na Izgled->Izbornici->Izmjenjivač jezika i odaberite Suprotni jezik.','TranslatePress gettext database optimization failed.'=>'Optimizacija gettext baze podataka za TranslatePress nije uspjela.','Retry'=>'Pokušaj ponovno','TranslatePress needs to optimize its gettext database tables. Back up the database, then <a href="%s">start the optimization</a>.'=>'TranslatePress mora optimizirati tablice gettext baze podataka. Napravite sigurnosnu kopiju baze podataka, zatim <a href="%s">pokrenite optimizaciju</a>.','Pending gettext database optimization'=>'Optimizacija gettext baze podataka na čekanju','Optimize TranslatePress database tables'=>'Optimizirajte tablice baze podataka TranslatePress','<a href="%s">Click here</a> to access the database optimization tool.'=>'<a href="%s">Kliknite ovdje</a> za pristup alatu za optimizaciju baze podataka.','It helps remove possible duplicate translations, clear unnecessary data and repair possible metadata issues.'=>'Pomaže u uklanjanju mogućih dupliciranih prijevoda, brisanju nepotrebnih podataka i popravljanju mogućih problema s metapodacima.','<a href="%s" target="_blank">Here</a> you can observe the last 5 SQL errors relevant to TranslatePress if they exist.'=>'<a href="%s" target="_blank">Ovdje</a> možete uočiti posljednjih 5 SQL pogrešaka relevantnih za TranslatePress ako postoje.','Troubleshooting'=>'Rješavanje problema','Exclude Gettext strings'=>'Izuzimanje nizova Gettext','Debug'=>'Ispravljanje grešaka','Custom languages'=>'Prilagođeni jezici','Miscellaneous options'=>'Različite opcije','Language Switcher'=>'Izmjenjivač jezika','Exclude strings & pages'=>'Isključi nizove i stranice','Automatic Translation Memory'=>'Automatska memorija za prevođenje','Serve same translation for similar text. The strings need to have a percentage of 95% similarity.<br>Helps prevent losing existing translation when correcting typos or making minor adjustments to the original text. <br>If a translation already exists for a very similar original string, it will automatically be used for the current original string.<br>Does not work when making changes to a text that is part of a translation block unless the new text is manually merged again in a translation block.<br>Each string needs to have a minimum of 50 characters.'=>'Poslužite isti prijevod za sličan tekst. Nizovi moraju imati postotak sličnosti od 95%. <br>Sprječava gubitak postojećeg prijevoda prilikom ispravljanja pogrešaka pri upisu ili manjih prilagodbi izvornog teksta. <br>Ako prijevod već postoji za vrlo sličan izvorni niz, automatski će se koristiti za trenutni izvorni niz. <br>Ne funkcionira prilikom mijenjanja teksta koji je dio prijevodnog bloka osim ako se novi tekst ručno ponovno ne spoji u prijevodni blok. <br>Svaki niz mora imati najmanje 50 znakova.','WARNING: This feature can negatively impact page loading times in secondary languages, particularly with large databases (for example websites with a lot of pages or products). If you experience slow loading times, disable this and try again.'=>'UPOZORENJE: Ova značajka može negativno utjecati na vrijeme učitavanja stranica na sekundarnim jezicima, posebno s velikim bazama podataka (na primjer web stranice s puno stranica ili proizvoda). Ako imate sporo vrijeme učitavanja, onemogućite to i pokušajte ponovno.','Fix missing dynamic content'=>'Ispravljanje dinamičkog sadržaja koji nedostaje','May help fix missing content inserted using JavaScript. <br> It shows dynamically inserted content in original language for a moment before the translation request is finished.'=>'Može pomoći ispraviti nedostajući sadržaj umetnut pomoću JavaScripta. <br> Prikazuje dinamički umetnuti sadržaj na izvornom jeziku na trenutak prije nego što završi zahtjev za prijevod.','Filter Gettext wrapping from post content and title'=>'Filtrirajte prelamanje Gettext-a prema sadržaju i naslovu objave','Filters gettext wrapping such as #!trpst#trp-gettext from all updated post content and post title. Does not affect previous post content. <br/><strong>Database backup is recommended before switching on.</strong>'=>'Filteri za gettext prelamanje kao što su #!trpst#trp-gettext iz svojeg sadržaja svih ažuriranih objava i naslova objava. Ne utječe na sadržaj prethodnih objava. <br/><strong>Preporučuje se izrada sigurnosne kopije baze podataka prije uključivanja.</strong>','Filter Gettext wrapping from post meta'=>'Filtriraj Gettext prelamanje iz meta objave','Filters gettext wrapping such as #!trpst#trp-gettext from all updated post meta. Does not affect previous post meta. <br/><strong>Database backup is recommended before switching on.</strong>'=>'Filtriranje gettext prelamanja kao što je #!trpst#trp-gettext iz svih ažuriranih meta podataka. Ne utječe na prethodne meta podatke. <br/><strong>Preporuča se izrada sigurnosne kopije baze podataka prije uključivanja.</strong>','TranslatePress'=>'TranslatePress','Abilities for managing TranslatePress configuration.'=>'Mogućnosti upravljanja TranslatePress konfiguracijom.','Add a translation language'=>'Dodaj jezik prijevoda','Adds a translation language to TranslatePress. Enforces the same per-license limit as the settings UI.'=>'Dodaje jezik prijevoda u TranslatePress. Primjenjuje isto ograničenje po licenci kao i sučelje postavki.','WordPress locale code (e.g. fr_FR, de_DE).'=>'WordPress jezični kôd (npr. fr_FR, de_DE).','Optional URL slug. Defaults to the ISO language code if omitted.'=>'Neobavezni URL slug. Ukoliko se izostavi, zadana vrijednost je ISO jezični kôd.','Set TranslatePress license key'=>'Postavi TranslatePress licencni ključ','Saves a TranslatePress license key and triggers a remote license check, mirroring the onboarding flow.'=>'Sprema TranslatePress licencni ključ i pokreće udaljenu provjeru licence, oponašajući tijek početnog postavljanja.','The license key to activate.'=>'Licencni ključ za aktivaciju.','Enable Automatic Translation'=>'Omogućite automatski prijevod','Turns on Automatic Translation. A valid TranslatePress license is required only when the resolved engine is TranslatePress AI (mtapi); Google Translate and DeepL do not require one. If no engine is passed and none is configured, defaults to mtapi.'=>'Uključuje automatsko prevođenje. Valjana licenca za TranslatePress potrebna je samo kada je odabrani stroj TranslatePress AI (mtapi); Google Translate i DeepL ne zahtijevaju licencu. Ako nije predan niti konfiguriran nijedan stroj, zadano je mtapi.','Optional translation-engine slug to select (e.g. "mtapi", "google_translate_v2", "deepl"). When omitted, keeps the already-configured engine, or defaults to "mtapi" if none is configured.'=>'Opcionalni slug stroja za prevođenje za odabir (npr. "mtapi", "google_translate_v2", "deepl"). Ako se izostavi, zadržava već konfigurirani stroj, odnosno zadano je "mtapi" ako nijedan nije konfiguriran.','List configured languages'=>'Prikaži konfigurirane jezike','Returns the languages currently configured in TranslatePress, including the default language and per-language slug/publish state.'=>'Vraća jezike trenutno konfigurirane u TranslatePressu, uključujući zadani jezik te slug/stanje objave za svaki jezik.','List available language codes'=>'Prikaži dostupne jezične kôdove','Returns the full catalog of language codes TranslatePress recognizes, with their English names.'=>'Vraća potpuni katalog jezičnih kôdova koje TranslatePress prepoznaje, s njihovim engleskim nazivima.','Remove a translation language'=>'Ukloni jezik prijevoda','Removes a configured translation language. The default language cannot be removed without first reassigning the default.'=>'Uklanja konfigurirani jezik prijevoda. Zadani jezik nije moguće ukloniti bez prethodnog ponovnog postavljanja zadanog jezika.','Locale code of the language to remove.'=>'Jezični kôd jezika koji se uklanja.','Update a translation language'=>'Ažuriraj jezik prijevoda','Replaces the slug and publish status of an already-configured translation language.'=>'Zamjenjuje slug i status objave već konfiguriranog jezika prijevoda.','Locale code of the language to update.'=>'Jezični kôd jezika koji se ažurira.','URL slug for this language.'=>'URL slug za ovaj jezik.','Whether this language is published on the front end.'=>'Je li ovaj jezik objavljen na javnoj stranici.','Set the default language'=>'Postavi zadani jezik','Promotes an already-configured language to be the site default. The previous default remains in the translation languages list.'=>'Promiče već konfigurirani jezik u zadani jezik stranice. Prethodni zadani jezik ostaje na popisu jezika prijevoda.','Locale code to promote to default. Must already be a configured translation language.'=>'Jezični kôd koji se postavlja kao zadani. Mora biti već konfigurirani jezik prijevoda.','You do not have permission to manage TranslatePress settings.'=>'Nemate dopuštenje za upravljanje TranslatePress postavkama.','Invalid language code. Allowed characters: A-Z, a-z, 0-9, hyphen, underscore.'=>'Nevažeći jezični kôd. Dopušteni znakovi: A-Z, a-z, 0-9, crtica, podvlaka.','Language code "%s" is not recognized by TranslatePress.'=>'Jezični kôd "%s" nije prepoznat od strane TranslatePress.','Language "%s" is already configured.'=>'Jezik "%s" je već konfiguriran.','Your current license allows up to %d additional language(s). Upgrade or activate a Pro license to add more.'=>'Vaša trenutna licenca omogućuje dodavanje do %d jezika. Nadogradite ili aktivirajte Pro licencu da biste dodali više.','TranslatePress rejected the new language during settings sanitization.'=>'TranslatePress je odbacio novi jezik tijekom čišćenja postavki.','Enabling Automatic Translation with the TranslatePress AI engine requires an active TranslatePress license. Activate a license first with translatepress/set-license-key, or pass a different engine (e.g. "google_translate_v2", "deepl").'=>'Omogućavanje automatskog prevođenja pomoću stroja TranslatePress AI zahtijeva aktivnu licencu za TranslatePress. Prvo aktivirajte licencu pomoću translatepress/set-license-key, ili odaberite drugi stroj (npr. "google_translate_v2", "deepl").','Your license key expired on %s.'=>'Vaš licencni ključ istekao je %s.','Your license key has expired.'=>'Vaš licenčni ključ je istekao.','Your license key has been disabled.'=>'Vaš licencni ključ je onemogućen.','Your TranslatePress license key is invalid or missing.'=>'Vaš TranslatePress licenčni ključ nije valjan ili nedostaje.','Your license key is disabled for this URL. Re-enable it from your TranslatePress account.'=>'Vaš licenčni ključ je onemogućen za ovaj URL. Ponovno ga omogućite putem svog TranslatePress računa.','License key mismatch. The license you entered does not match the TranslatePress version you have installed.'=>'Nepodudaranje licenčnog ključa. Unesena licenca ne odgovara verziji TranslatePress koju imate instaliranu.','Your license key has reached its activation limit.'=>'Vaš licencni ključ dosegao je ograničenje aktivacije.','An error occurred while activating the license, please try again.'=>'Došlo je do pogreške prilikom aktivacije licence, pokušajte ponovno.','Language "%s" is not currently configured.'=>'Jezik "%s" trenutno nije konfiguriran.','The default language cannot be removed. Set another language as default first.'=>'Zadani jezik nije moguće ukloniti. Prvo postavite drugi jezik kao zadani.','Slug is empty after sanitization. Use only URL-safe characters.'=>'Slug je prazan nakon sanitizacije. Koristite samo znakove sigurne za URL.','Language "%s" is not currently configured. Add it first with translatepress/add-language.'=>'Jezik "%s" trenutno nije konfiguriran. Dodajte ga prvo pomoću translatepress/add-language.','The default language is always published and cannot be unpublished.'=>'Zadani jezik je uvijek objavljen i ne može se poništiti objava.','Slug "%1$s" is already in use by language "%2$s".'=>'Slug "%1$s" već je u upotrebi za jezik "%2$s".','TranslatePress rejected the new settings during sanitization.'=>'TranslatePress je odbio nove postavke tijekom sanitizacije.','Advanced'=>'Napredno','Are you sure you want to remove this item?'=>'Jeste li sigurni da želite ukloniti ovu stavku?','Remove'=>'Ukloni','Add'=>'Dodaj','Select...'=>'Odaberi...','An error occurred, please try again.'=>'Došlo je do greške, pokušajte ponovno.','Your license key is disabled for this URL. Re-enable it from <a target="_blank" href="https://translatepress.com/account/?utm_source=wp-dashboard&utm_medium=client-site&utm_campaign=license-deactivated">https://translatepress.com/account</a> -> Manage Sites.'=>'Vaš licenčni ključ je onemogućen za ovaj URL. Ponovno ga omogućite iz <a target="_blank" href="https://translatepress.com/account/?utm_source=wp-dashboard&utm_medium=client-site&utm_campaign=license-deactivated">https://translatepress.com/account</a> -> Upravljanje stranicama.','<p><strong>License key mismatch.</strong> The license you entered doesn’t match the TranslatePress version you have installed.</p><p>Please check that you’ve installed the correct version for your license from your TranslatePress account.</p>'=>'<p><strong>Neusklađenost licenčnog ključa.</strong> Licenca koju ste unijeli ne odgovara verziji TranslatePress koju ste instalirali.</p><p>Provjerite jeste li instalirali ispravnu verziju za svoju licencu sa svog TranslatePress računa.</p>','If you have only the free plugin installed but added a paid license, please install the paid plugin from your TranslatePress account.'=>'Ako imate instaliran samo besplatni dodatak, ali ste dodali plaćenu licencu, molimo instalirajte plaćeni dodatak sa svog TranslatePress računa.','Upgrade your plan to add more sites. %1$sUpgrade now%2$s'=>'Nadogradite svoju tarifu da biste dodali više web stranica. %1$sNadogradite sada%2$s','You have successfully activated your license'=>'Uspješno ste aktivirali svoju licencu','[%s] Low TranslatePress AI Words'=>'[%s] Niska razina TranslatePress AI riječi','upgrade your plan'=>'nadogradite svoj plan','upgrade your plan or get extra AI Words'=>'nadogradite svoj plan ili nabavite dodatne AI riječi','TranslatePress AI words are running low on your site.'=>'TranslatePress AI riječi su na izmaku na vašoj web stranici.','Current status: %s words remaining'=>'Trenutni status: preostalo %s riječi','Once the remaining AI words run out, automatic translation through TranslatePress AI will be paused.'=>'Kad preostale AI riječi ponestanu, automatski prijevod putem TranslatePress AI-a bit će pauziran.','To continue translating your content, please %1$s over at %2$s'=>'Da biste nastavili prevoditi svoj sadržaj, molimo vas da %1$s na %2$s.','Manage Notification: %s'=>'Upravljanje obavijestima: %s','Others'=>'Ostali','Restrict by Language'=>'Ograniči prema jeziku','Exclude from Language'=>'Isključi iz jezika','Restrict element to language'=>'Ograničite element na jezik','Show this element only in one language.'=>'Prikažite ovaj element samo na jednom jeziku.','Enable translation'=>'Omogući prijevod','Allow translation to the corresponding language only if the content is written in the default language.'=>'Dopusti prijevod na odgovarajući jezik samo ako je sadržaj napisan na zadanom jeziku.','Select language'=>'Odaberite jezik','Choose in which language to show this element.'=>'Odaberite na kojem jeziku želite prikazati ovaj element.','Exclude element from language'=>'Izuzimanje elementa iz jezika','Exclude this element from specific languages.'=>'Izuzmite ovaj element iz određenih jezika.','Select languages'=>'Odaberite jezike','Choose from which languages to exclude this element.'=>'Odaberite iz kojih jezika želite izuzeti ovaj element.','This element will still be visible when you are translating your website through the Translation Editor.'=>'Ovaj će element i dalje biti vidljiv kada prevodite svoju web stranicu putem uređivača prijevoda.','The content of this element should be written in the default language.'=>'Sadržaj ovog elementa trebao bi biti napisan na zadanom jeziku.','<strong>TranslatePress</strong> encountered SQL errors. <a href="%s" title="View TranslatePress SQL Errors">Check out the errors</a>.'=>'<strong>TranslatePress</strong> je naišao na SQL pogreške. <a href="%s" title="View TranslatePress SQL Errors">Provjerite pogreške</a>.','Automatic translation has been disabled.'=>'Automatski prijevod je onemogućen.','Logged errors'=>'Zabilježene greške','These are the most recent 5 errors logged by TranslatePress:'=>'Ovo je najnovijih 5 pogrešaka koje je zabilježio TranslatePress:','Yes'=>'Da','Why are these errors occuring'=>'Zašto se pojavljuju ove pogreške','If TranslatePress detects something wrong when executing queries on your database, it may disable the Automatic Translation feature in order to avoid any extra charging by Google/DeepL. Automatic Translation needs to be manually turned on, after you solve the issues.'=>'Ako TranslatePress otkrije nešto pogrešno prilikom izvršavanja upita u vašoj bazi podataka, može onemogućiti značajku automatskog prijevoda kako bi izbjegao dodatno naplaćivanje od strane Googlea/DeepL-a. Automatski prijevod potrebno je ručno uključiti nakon što riješite probleme.','The SQL errors detected can occur for various reasons including missing tables, missing permissions for the SQL user to create tables or perform other operations, problems after site migration or changes to SQL server configuration.'=>'Otkrivene SQL pogreške mogu se pojaviti iz različitih razloga, uključujući tablice koje nedostaju, nedostajuće dozvole za SQL korisnika za stvaranje tablica ili izvođenje drugih operacija, probleme nakon migracije web-mjesta ili promjene konfiguracije SQL servera.','What you can do in this situation'=>'Što možete učiniti u ovoj situaciji','Plan A.'=>'Plan A.','Go to Settings -> TranslatePress -> General tab and Save Settings. This will regenerate the tables using your current SQL settings. Check if no more errors occur while browsing your website in a translated language. Look at the timestamps of the errors to make sure you are not seeing the old errors. Only the most recent 5 errors are displayed.'=>'Idite na Postavke -> TranslatePress -> karticu Općenito i Spremi postavke. Ovo će ponovno generirati tablice pomoću vaših trenutnih SQL postavki. Provjerite pojavljuju li se više pogreške tijekom pregledavanja vaše web stranice na prevedenom jeziku. Pogledajte vremenske oznake pogrešaka kako biste bili sigurni da ne vidite stare pogreške. Prikazuje se samo zadnjih 5 grešaka.','Plan B.'=>'Plan B.','If your problem isn\'t solved, try the following steps:'=>'Ako problem nije riješen, pokušajte sljedeće korake:','Create a backup of your database'=>'Stvorite sigurnosne kopije baze podataka','Create a copy of each translation table where you encounter errors. You can copy the table within the same database (trp_dictionary_en_us_es_es_COPY for example) -- perform this step only if you want to keep the current translations'=>'Napravite kopiju svake tablice prijevoda u kojoj naiđete na greške. Možete kopirati tablicu unutar iste baze podataka (trp_dictionary_en_us_es_es_COPY na primjer) -- izvršite ovaj korak samo ako želite zadržati trenutne prijevode','Remove the trouble tables by executing the DROP function on them'=>'Uklonite tablice problema izvršavanjem funkcije DROP na njima','Go to Settings -> TranslatePress -> General tab and Save Settings. This will regenerate the tables using your current SQL server.'=>'Idite na Postavke -> TranslatePress -> karticu Općenito i Spremi postavke. Ovo će ponovno generirati tablice pomoću vašeg trenutnog SQL poslužitelja.','Copy the relevant content from the duplicated tables (trp_dictionary_en_us_es_es_COPY for example) in the newly generated table (trp_dictionary_en_us_es_es) -- perform this step only if you want to keep the current translations'=>'Kopirajte relevantni sadržaj iz dupliciranih tablica (trp_dictionary_en_us_es_es_COPY na primjer) u novogeneriranu tablicu (trp_dictionary_en_us_es_es) -- izvršite ovaj korak samo ako želite zadržati trenutne prijevode','Test it to see if everything is working. If something went wrong, you can restore the backup that you\'ve made at the first step. Check if no more errors occur while browsing your website in a translated language. Look at the timestamps of the errors to make sure you are not seeing the old errors. Only the most recent 5 errors are displayed.'=>'Testirajte ga da vidite radi li sve. Ako je nešto pošlo krivo, možete vratiti sigurnosnu kopiju koju ste napravili u prvom koraku. Provjerite pojavljuju li se više pogreške tijekom pregledavanja vaše web stranice na prevedenom jeziku. Pogledajte vremenske oznake pogrešaka kako biste bili sigurni da ne vidite stare pogreške. Prikazuje se samo zadnjih 5 grešaka.','Plan C.'=>'Plan C.','If your problem still isn\'t solved, try asking your hosting about your errors. The most common issue is missing permissions for the SQL user, such as the Create Tables permission.'=>'Ako vaš problem još uvijek nije riješen, pokušajte pitati svog hostinga o svojim pogreškama. Najčešći problem je nedostatak dopuštenja za SQL korisnika, kao što je dopuštenje za stvaranje tablica.','Could not install. Try again from <a href="%s" >Plugins Dashboard.</a>'=>'Nije moguće instalirati. Pokušajte ponovno s <a href="%s" >nadzorne ploče dodataka.</a>','Settings scope unknown.'=>'Opseg postavki nepoznat.','Legacy disabled.'=>'Naslijeđeno je onemogućeno.','Change language to %s'=>'Promijenite jezik u %s','Automatic Translation'=>'Automatski prijevod','Unsupported languages'=>'Nepodržani jezici','The selected automatic translation engine does not provide support for these languages.<br>You can still manually translate pages in these languages using the Translation Editor.'=>'Odabrani mehanizam za automatsko prevođenje ne pruža podršku za ove jezike.<br>I dalje možete ručno prevoditi stranice na ovim jezicima pomoću Uređivača prijevoda.','General'=>'Općenito','Glossary'=>'Rječnik','API key validation failed.'=>'Provjera valjanosti API ključa nije uspjela.','API key verification was successful.'=>'Provjera API ključa bila je uspješna.','Please enter your Google Translate key.'=>'Molim, unesite svoj Google Translate ključ.','Not TranslatePress onboarding page.'=>'Nije stranica za uključivanje TranslatePressa.','Step %s does not exist'=>'Korak %s ne postoji','Welcome'=>'Dobro došli','Add Languages'=>'Dodaj jezike','Enable Addons'=>'Omogući dodatke','Finalize'=>'Završi','Exit Setup'=>'Napusti postavljanje','Upgrade'=>'Nadogradnja','Nothing here'=>'Ovdje nema ništa','Your <strong>TranslatePress</strong> license is missing or invalid. <br/>Please %1$sregister your copy%2$s to enable automatic website translation via TranslatePress AI, premium addons, automatic updates and support. Need a license key? %3$sPurchase one now%4$s'=>'Vaša licenca <strong>za TranslatePress</strong> nedostaje ili je nevažeća. <br/>Registrirajte %1$ssvoj primjerak%2$s kako biste omogućili automatski prijevod web stranice putem TranslatePress AI, premium dodataka, automatskih ažuriranja i podrške. Trebate licenčni ključ? %3$sKupite ga odmah%4$s','Your license is disabled for this URL. Re-enable it from <a target="_blank" href="https://translatepress.com/account/?utm_source=wp-dashboard&utm_medium=client-site&utm_campaign=license-deactivated">https://translatepress.com/account</a> -> Manage Sites.'=>'Vaša je licenca onemogućena za ovaj URL. Ponovno ga omogućite iz <a target="_blank" href="https://translatepress.com/account/?utm_source=wp-dashboard&utm_medium=client-site&utm_campaign=license-deactivated">https://translatepress.com/account</a> -> Upravljanje stranicama.','You have reached the activation limit for your <strong>%1$s</strong> license. <br/>Manage your active sites from %2$s your account %3$s.'=>'Dosegli ste ograničenje aktivacije za svoju <strong>%1$s</strong> licencu. <br/>Upravljajte svojim aktivnim web stranicama sa %2$s svog računa %3$s.','License key mismatch. The license you entered doesn’t match the <strong>%1$s</strong> version you have installed. <br/>Please check that you’ve installed the correct version for your license from your %2$sTranslatePress account%3$s.'=>'Neusklađenost licenčnog ključa. Licenca koju ste unijeli ne odgovara verziji koju <strong>%1$s</strong> ste instalirali. <br/>Provjerite jeste li instalirali ispravnu verziju za svoju licencu sa svog %2$sTranslatePress računa%3$s.','<br/>If you have only the free plugin installed but added a paid license, please install the paid plugin from your TranslatePress account.'=>'<br/>Ako imate instaliran samo besplatni dodatak, ali ste dodali plaćenu licencu, molimo instalirajte plaćeni dodatak sa svog TranslatePress računa.','Your <strong>TranslatePress</strong> license has expired. <br/>Please %1$sRenew Your Licence%2$s to continue receiving access to automatic translations via TranslatePress AI, premium addons, product downloads, and automatic updates. %3$sRenew now %4$s'=>'Vaša licenca <strong>za TranslatePress</strong> je istekla. <br/>Obnovite %1$ssvoju licencu%2$s kako biste nastavili primati pristup automatskim prijevodima putem TranslatePress AI, premium dodataka, preuzimanja proizvoda i automatskih ažuriranja. %3$sObnovi odmah %4$s','Error: '=>'Greška: ','Something went wrong, please try again.'=>'Nešto je pošlo po zlu, pokušajte ponovno.','Your <strong>TranslatePress</strong> license will expire on %1$s. Please %2$sRenew Your Licence%3$s to continue receiving access to automatic translations via TP AI, premium addons, product downloads and automatic updates. %4$sRenew Now%5$s'=>'Vaša licenca <strong>za TranslatePress</strong> istječe dana %1$s. Obnovite %2$ssvoju licencu%3$s kako biste nastavili primati pristup automatskim prijevodima putem TP AI, premium dodacima, preuzimanjima proizvoda i automatskim ažuriranjima. %4$sObnovi odmah%5$s','Please %1$senter%2$s your license key to enable %3$s automatic translation.'=>'Molimo %1$sunesite%2$s svoj licenčni ključ kako biste omogućili %3$s automatski prijevod.','%1$s automatic translation requires an active license. Please %2$srenew%3$s your license or purchase a new one %4$shere%5$s.'=>'%1$s automatsko prevođenje zahtijeva aktivnu licencu. Molimo %2$sobnovite%3$s svoju licencu ili kupite novu %4$sovdje%5$s.','You have less than 5,000 TranslatePress AI words remaining. To continue automatically translating your website, please %spurchase additional AI words at a discount from your account%s.'=>'Ostalo vam je manje od 5,000 TranslatePress AI riječi. Da biste nastavili s automatskim prevođenjem svoje web stranice, %skupite dodatne AI riječi s popustom sa svog računa%s.','You do not have a valid license for <strong>TranslatePress</strong>. %1$sGet one for free%2$s to get access to TranslatePress AI.'=>'Nemate važeću licencu za <strong>TranslatePress</strong>. %1$sNabavite jednu besplatno%2$s da biste dobili pristup TranslatePress AI.',' Error: '=>' Greška: ','<strong>NEW:</strong> The <strong>Different Domain per Language</strong> add-on is here! Boost your global SEO and create a local experience with country-specific domains like .de or .fr. <a href="https://translatepress.com/docs/addons/different-domain-per-language/?utm_source=wp-dashboard&utm_medium=client-site&utm_campaign=new-addon-ddpl" target="_blank">Learn more</a>.'=>'<strong>NOVO:</strong> Stigao je dodatak <strong>Different Domain per Language</strong>! Poboljšajte svoj globalni SEO i stvorite lokalno iskustvo s domenama specifičnim za zemlju poput .de ili .fr. <a href="https://translatepress.com/docs/addons/different-domain-per-language/?utm_source=wp-dashboard&utm_medium=client-site&utm_campaign=new-addon-ddpl" target="_blank">Saznajte više</a>.','<strong>NEW:</strong> The <strong>Different Domain per Language</strong> add-on is here! Boost your global SEO and create a local experience with country-specific domains like .de or .fr. Upgrade to <a href="https://translatepress.com/pricing/?utm_source=wp-dashboard&utm_medium=client-site&utm_campaign=new-addon-ddpl-upsell" target="_blank">TranslatePress Business or Developer</a> to access it + more premium perks!'=>'<strong>NOVO:</strong> Stigao je dodatak <strong>Different Domain per Language</strong>! Poboljšajte svoj globalni SEO i stvorite lokalno iskustvo s domenama specifičnim za zemlju poput .de ili .fr. Nadogradite na <a href="https://translatepress.com/pricing/?utm_source=wp-dashboard&utm_medium=client-site&utm_campaign=new-addon-ddpl-upsell" target="_blank">TranslatePress Business ili Developer</a> kako biste mu pristupili + još više premium pogodnosti!','The daily quota for machine translation characters exceeded. Please check the <strong>TranslatePress -> <a href="%s">Automatic Translation</a></strong> page for more information.'=>'Prekoračena je dnevna kvota za znakove strojnog prevođenja. Za više informacija provjerite <strong>stranicu TranslatePress -> <a href="%s">Automatski prijevod</a></strong>.','Marketing optin'=>'Uključivanje u marketing','Opt in to our security and feature updates notifications, and non-sensitive diagnostic tracking.'=>'Uključite se u naše obavijesti o sigurnosnim ažuriranjima i ažuriranjima značajki te neosjetljivom dijagnostičkom praćenju.','TranslatePress Preferred User Language'=>'TranslatePress Preferirani korisnički jezik','Preferred language to navigate the site'=>'Preferirani jezik za navigaciju stranicom','The language is automatically set based by the last visited language by the user.'=>'Jezik se automatski postavlja na temelju posljednjeg jezika koji je korisnik posjetio.','Always use this language'=>'Uvijek koristite ovaj jezik','By checking this setting the preferred language will remain the one selected above, without the possibility of being changed in the frontend.<br>This language will be used in different operations such as sending email to the user.'=>'Provjerom ove postavke preferirani jezik ostat će gore odabrani, bez mogućnosti promjene u sučelju. <br>Ovaj jezik će se koristiti u različitim operacijama kao što je slanje e-pošte korisniku.','Hello! Seems like you\'ve been using <strong>TranslatePress</strong> for a while now to translate your website. That\'s awesome! '=>'Pozdrav! Čini se da već neko vrijeme koristite <strong>TranslatePress</strong> za prevođenje svoje web stranice. To je sjajno! ','If you can spare a few moments to rate it on WordPress.org it would help us a lot (and boost my motivation).'=>'Ako možete odvojiti nekoliko trenutaka da ga ocijenite na WordPress.org to bi nam puno pomoglo (i povećalo moju motivaciju).','~ Razvan, developer of TranslatePress'=>'~ Razvan, programer TranslatePressa','Rate TranslatePress on WordPress.org plugin page'=>'Ocijeni TranslatePress na WordPress.org stranici dodatka','Ok, I will gladly help!'=>'U redu, rado ću pomoći!','No, thanks.'=>'Ne, hvala.','Full Language Names'=>'Puni nazivi jezika','Short Language Names'=>'Kratki nazivi jezika','Flags with Full Language Names'=>'Zastave s punim nazivima jezika','Flags with Short Language Names'=>'Zastave s kratkim jezičnim nazivima','Only Flags'=>'Samo zastave','Full Language Names No HTML'=>'Puni nazivi jezika bez HTML-a','Bottom Right'=>'Dolje desno','Bottom Left'=>'Dolje lijevo','Top Right'=>'Gore desno','Top Left'=>'Gore lijevo','Dark'=>'Tamno','Light'=>'Svijetlo','Install & Activate'=>'Instaliraj i aktiviraj','Invalid language code. Please try again.'=>'Nevažeći kod jezika. Pokušajte ponovno.','Language codes can contain only A-Z a-z 0-9 - _ characters. Check your language codes in TranslatePress General Settings.'=>'Kodovi jezika mogu sadržavati samo A-Z a-z 0-9 - _ znakova. Provjerite kodove jezika u TranslatePress Opće postavke.','Error! Duplicate URL slug values.'=>'Greška! Duplicirane vrijednosti URL-a.','You cannot select two languages that have the same <a href="https://en.wikipedia.org/wiki/List_of_ISO_639-1_codes" target="_blank">iso code</a> but different formalities because doing so will lead to duplicate <a href="https://developers.google.com/search/docs/specialty/international/localized-versions" target="_blank">hreflang tags</a>.'=>'Ne možete odabrati dva jezika koji imaju isti <a href="https://en.wikipedia.org/wiki/List_of_ISO_639-1_codes" target="_blank">iso kod</a>, ali različite formalnosti jer će to dovesti do duplikata <a href="https://developers.google.com/search/docs/specialty/international/localized-versions" target="_blank">hreflang oznake</a>.','Duplicate language detected.<br>Each language can only be added once to ensure accurate translation management.<br> Please change the duplicate language entry and try again. '=>'Otkriven je dvostruki jezik.<br>Svaki jezik može se dodati samo jednom kako bi se osiguralo točno upravljanje prijevodom.<br> Promijenite unos duplikata jezika i pokušajte ponovno. ','Current Language'=>'Trenutačni jezik','Opposite Language'=>'Suprotni jezik','Addons'=>'Dodaci','Settings'=>'Postavke','Pro Features'=>'Pro značajke','Activate License'=>'Aktiviraj licencu','Need Help?'=>'Trebate pomoć?','Recent community discussions'=>'Nedavne rasprave u zajednici','Loading...'=>'Učitavanje ...','Unable to load forum posts'=>'Nije moguće učitati forumske objave','Ask a Question'=>'Postavite pitanje','View All Topics'=>'Pogledajte sve teme','by'=>'od','Have a question?'=>'Imate pitanje?','Get help directly from the plugin developers, suggest improvements, or share your feedback!'=>'Zatražite pomoć izravno od developera plugina, predložite poboljšanja ili podijelite svoje povratne informacije!','Tip for faster help:'=>'Savjet za bržu pomoć:','Include what you tried, what you expected, and what happened. Screenshots help!'=>'Uključuje što ste pokušali, što ste očekivali i što se dogodilo. Snimke zaslona pomažu!','Toggle support chat'=>'Prebaci na chat za podršku','Ask the community'=>'Pitaj zajednicu','Close'=>'Zatvori','Empty feed response'=>'Odziv praznog sadržaja','Unable to parse feed'=>'Nije moguće raščlaniti sadržaj','Just now'=>'Upravo sad','%d hour ago'=>'%d sat prije' . "\0" . '%d sata prije' . "\0" . '%d sati prije','%d day ago'=>'%d dan prije' . "\0" . '%d dana prije' . "\0" . '%d dana prije','Source'=>'Izvor','Srcset'=>'Izvorni skup','Alt attribute'=>'Zamjenska svojstva','Title attribute'=>'Svojstva naslova','Anchor link'=>'Anchor poveznica','Placeholder attribute'=>'Svojstva rezerviranog mjesta','Submit attribute'=>'Pošalji svojstva','Text'=>'Tekst','Video Poster'=>'Video plakat','plural form'=>'oblik množine','one'=>'jedan','few'=>'nekoliko','many'=>'mnogo','other'=>'drugo','Saved'=>'Spremljeno','Save'=>'Spremi','Saving translation...'=>'Spremanje prijevoda...','You have unsaved changes!'=>'Imate nespremljene promjene!','Discard changes'=>'Odbaci promjene','Discard All'=>'Odbaci sve','Loading Strings...'=>'Učitavanje nizova...','Select string to translate...'=>'Odaberite niz za prijevod...','Close Editor'=>'Zatvori uređivač','From'=>'Od','To'=>'Do','Add Media'=>'Dodavanje medija','Other languages'=>'Ostali jezici','Context'=>'Kontekst','View Website As'=>'Pogledajte web stranicu kao','Available in our Pro Versions'=>'Dostupno u našim Pro verzijama','Select or Upload Media'=>'Odaberite ili prenesite medijske sadržaje','Use this media'=>'Use this media','Translate'=>'Prevedi','Translate entire block element'=>'Prevedi cijeli element bloka','Split block to translate strings individually'=>'Podijeli blok za pojedinačno prevođenje nizova','Save changes to translation. Shortcut: CTRL(⌘) + S'=>'Spremite promjene u prijevod. Prečac: CTRL(⌘) + S','Navigate to next string in dropdown list. Shortcut: CTRL(⌘) + ALT + Right Arrow'=>'Idite na sljedeći niz na padajućem popisu. Prečac: CTRL(⌘) + ALT + strelica desno','Navigate to previous string in dropdown list. Shortcut: CTRL(⌘) + ALT + Left Arrow'=>'Idite na prethodni niz na padajućem popisu. Prečac: CTRL(⌘) + ALT + strelica ulijevo','Discard all changes. Shortcut: CTRL(⌘) + ALT + Z'=>'Odbacite sve promjene. Prečac: CTRL(⌘) + ALT + Z','Discard changes to this text box. To discard changes to all text boxes use shortcut: CTRL(⌘) + ALT + Z'=>'Odbacite promjene u ovom tekstnom okviru. Da biste odbacili promjene u svim tekstnim okvirima, koristite prečac: CTRL(⌘) + ALT + Z','Dismiss tooltip'=>'Odbacivanje opisa','Quick Intro'=>'Brzi uvod','Are you sure you want to split this phrase into smaller parts?'=>'Jeste li sigurni da želite podijeliti ovu frazu na manje dijelove?','This string is not ready for translation yet. <br>Try again in a moment...'=>'Ovaj tekst još nije spreman za prijevod. <br>Pokušajte ponovo za trenutak...','For this option to work, please update the Browse as other role add-on to the latest version.'=>'Da bi ta opcija funkcionirala, ažurirajte dodatak Pregledaj kao drugu ulogu na najnoviju verziju.','To translate slugs, please update the SEO Pack add-on to the latest version.'=>'Da biste preveli slugove, ažurirajte dodatak SEO Pack na najnoviju verziju.','You can add a new language from <a href="%s">Settings->TranslatePress</a>'=>'Novi jezik možete dodati iz <a href="%s">Settings->TranslatePress</a>','However, you can still use TranslatePress to <strong style="background: #f5fb9d;">modify gettext strings</strong> available in your page.'=>'Međutim, još uvijek možete koristiti TranslatePress za <strong style="background: #f5fb9d;"> izmijeniti gettext nizove</strong> dostupne na vašoj stranici.','Strings that are user-created cannot be modified, only those from themes and plugins.'=>'Nizovi koje je stvorio korisnik ne mogu se mijenjati, samo oni iz tema i dodataka.','Extra Translation Features'=>'Dodatne značajke prijevoda','Support for 130+ Extra Languages'=>'Podrška za 130+ dodatnih jezika','Access to TranslatePress AI'=>'Pristup TranslatePress AI','Translate SEO Title, Description, Slug'=>'Prevedi SEO naslov, opis, slug','Publish only when translation is complete'=>'Objavite samo kada je prijevod dovršen','Translate by Browsing as User Role'=>'Prevedi pregledavanjem kao korisničku ulogu','Different Menu Items for each Language'=>'Različite stavke izbornika za svaki jezik','Upgrade to PRO'=>'Nadogradite na PRO','Upgrade to PRO with our biggest discount of the year!'=>'Nadogradite na PRO uz naš najveći popust u godini!','This Black Friday, get access to these features and more at a fraction of the costs:'=>'Ovog Crnog petka ostvarite pristup ovim značajkama i još mnogo toga uz djelić troškova:','No available suggestions'=>'Nema dostupnih prijedloga','Suggestions from translation memory'=>'Prijedlozi iz prevoditeljske memorije','Click to Copy'=>'Kliknite za kopiranje','Human Translation'=>'Ljudski prijevod','Machine Translation'=>'Strojno prevođenje','Gettext File Translation'=>'Prijevod gettext datoteka','Text on this page is %s% translated into all languages.'=>'Tekst na ovoj stranici je %s% preveden na sve jezike.','%1$s% of text on this page is translated into %2$s.'=>'%1$s% teksta na ovoj stranici prevedeno je u %2$s.','This page is %1$s% translated into %2$s.'=>'Ova stranica je %1$s% prevedena na %2$s.','The slug that you are trying to edit is present in other slug types:%s%. Editing it will replace each occurrence, regardless of the current type.'=>'Slug koji pokušavate urediti prisutan je u drugim vrstama slugova:%s%. Uređivanje će zamijeniti svako pojavljivanje, bez obzira na trenutnu vrstu.','Hover any text on the page, click %s,<br> then modify the translation in the sidebar.'=>'Zadržite pokazivač miša na bilo kojem tekstu na stranici, kliknite %s,<br> zatim promijenite prijevod na bočnoj traci.','Don\'t forget to Save Translation. Use keyboard shortcut CTRL(⌘) + S'=>'Ne zaboravite spremiti prijevod. Koristite prečac na tipkovnici CTRL(⌘) + S','Switch language to see the translation changes directly on the page.'=>'Prebacite jezik da biste izravno vidjeli promjene u prijevodu na stranici.','Search for any text in this page in the dropdown.'=>'Pretražite bilo koji tekst na ovoj stranici u padajućem izborniku.','Your %s license has <span class="trp-license-status-emphasized">expired</span>.'=>'Vaša %s licencija je <span class="trp-license-status-emphasized">istekla</span>.','<strong>This Black Friday, renew your license at a special price</strong> to continue receiving access to product downloads, automatic updates, and support.'=>'<strong>Ovaj Crni petak, obnovite svoju licencu po posebnoj cijeni</strong> kako biste nastavili primati pristup preuzimanjima proizvoda, automatskim ažuriranjima i podršci.','Get Deal'=>'Uzmite ponudu','Please renew your license to continue receiving access to TranslatePress AI, premium addons, automatic updates and support.'=>'Obnovite svoju licencu kako biste nastavili primati pristup TranslatePress AI, premium dodacima, automatskim ažuriranjima i podršci.','Renew Now'=>'Obnovi sada','Your %s license was <span class="trp-license-status-emphasized">refunded</span>.'=>'Vaša %s licenca je <span class="trp-license-status-emphasized">refundirana</span>.','Please purchase a new license to continue receiving access to TranslatePress AI, premium addons, automatic updates and support.'=>'Kupite novu licencu kako biste nastavili primati pristup TranslatePress AI, premium dodacima, automatskim ažuriranjima i podršci.','Purchase a new license'=>'Kupite novu licencu','Your %s license is <span class="trp-license-status-emphasized">missing or invalid</span>.'=>'Vaša licenca <span class="trp-license-status-emphasized">nedostaje ili je nevažeća</span>%s.','Please enter a valid license to get access to TranslatePress AI, premium addons, automatic updates and support. Need a license key? %1$sPurchase one now%2$s'=>'Unesite važeću licencu kako biste dobili pristup TranslatePress AI, premium dodacima, automatskim ažuriranjima i podršci. Trebate licencni ključ? %1$sKupite ga sada%2$s','Enter a valid license'=>'Unesite važeću licencu','Meta Information'=>'Meta informacije','String List'=>'Popis nizova','Gettext Strings'=>'Gettext nizovi','Images'=>'Slike','Videos'=>'Video','Audios'=>'Audio','Dynamically Added Strings'=>'Dinamički dodani nizovi','Translation Editor'=>'Urednik prijevoda','Edit translations by visually selecting them on each site page'=>'Uredite prijevode tako da ih vizualno odaberete na svakoj stranici web stranice','String Translation'=>'Prijevod nizova','Edit url slug translations, plugins and theme translation (emails, forms etc.)'=>'Uredite prijevode url sluga, dodatke i prijevod tema (e-pošta, obrasci itd.)','Current User'=>'Trenutni korisnik','Logged Out'=>'Odjavljen','Translate Page'=>'Prevedi stranicu','Add a New Language'=>'Dodaj novi jezik','Your License is Invalid'=>'Vaša licenca je nevažeća','Get More AI Words (%d left)'=>'Nabavite više AI riječi (%d ostalo)','Opens post in the translation editor. Post must be saved as draft or published beforehand.'=>'Otvara objavu u uređivaču prijevoda. Objava mora biti spremljena kao skica ili prethodno objavljena.','Security check'=>'Sigurnosna provjera','<strong>Warning:</strong> Some strings have possibly incorrectly encoded characters. This may result in breaking the queries, rendering the page untranslated in live mode. Consider revising the following strings or their method of outputting.'=>'<strong>upozorenje:</strong> Neki nizovi imaju možda pogrešno kodirane znakove. To može rezultirati prekidom upita, čineći stranicu neprevedenom u načinu rada uživo. Razmislite o reviziji sljedećih nizova ili njihove metode ispisa.','IMPORTANT: It is strongly recommended to first backup the database!'=>'VAŽNO: Snažno se preporučuje prvo napraviti sigurnosnu kopiju baze podataka!','Are you sure you want to continue?'=>'Jeste li sigurni da želite nastaviti?','TranslatePress data update'=>'TranslatePress ažuriranje podataka','We need to update your translations database to the latest version.'=>'Moramo ažurirati vašu bazu podataka prijevoda na najnoviju verziju.','Updating will allow editing translations of localized text from plugins and theme. Existing translation will still work as expected.'=>'Ažuriranje će omogućiti uređivanje prijevoda lokaliziranog teksta iz dodataka i teme. Postojeći prijevod i dalje će funkcionirati prema očekivanjima.','Run the updater'=>'Pokrenite program za ažuriranje','Updating will allow editing translations of slugs. Existing translation will still work as expected.'=>'Ažuriranje će omogućiti uređivanje prijevoda slugova. Postojeći prijevod i dalje će funkcionirati prema očekivanjima.','Please activate the SEO Addon from <br/>WordPress -> Settings -> TranslatePress -> Addons section'=>'Aktivirajte SEO dodatak iz <br/>WordPress -> Postavke -> TranslatePress -> Odjeljak dodaci','Go to Addons'=>'Idi na dodaci','The SEO Pack add-on allows translation of all the URL slugs:'=>'Dodatak SEO Pack omogućuje prijevod svih URL slugova:','Taxonomy slugs'=>'Razvrstavanje slugova','Term slugs'=>'Pojam slug','Post slugs (this includes pages and custom post types)'=>'Slugovi objava (to uključuje stranice i prilagođene vrste objava)','Post type base slugs'=>'Slugovi bazirani na vrsti objave','WooCommerce slugs'=>'WooCommerce slugovi','The SEO Pack add-on is available with ALL premium versions of the plugin.'=>'Dodatak SEO Pack dostupan je sa SVIM premium verzijama dodatka.','Upgrade to Pro'=>'Nadogradite na Pro','Description'=>'Opis','Article Section'=>'Odjeljak članka','Article Tag'=>'Oznaka članka','OG Title'=>'OG Naslov','OG Site Name'=>'OG Naziv stranice','OG Description'=>'OG opis','OG Image Alt'=>'OG Alternativna slika','Twitter Title'=>'Twitter naslov','Twitter Description'=>'Twitter opis','Twitter Image Alt'=>'Twitter Alternativna slika','Page Title'=>'Naslov stranice','Dublin Core Title'=>'Dublin Core naslov','Dublin Core Description'=>'Dublin Core opis','OG Image'=>'OG slika','OG Image Secure URL'=>'OG Siguran URL slike','Twitter Image'=>'Twitter slika','Removing cdata dictionary strings for language %s...'=>'Uklanjanje nizova rječnika cdata za jezik %s...','Removing untranslated dictionary links for language %s...'=>'Uklanjanje neprevedenih poveznica rječnika za jezik %s...','Removing duplicated gettext strings for language %s...'=>'Uklanjanje dupliciranih gettext nizova za jezik %s...','Removing duplicated dictionary strings for language %s...'=>'Uklanjanje dupliciranih nizova rječnika za jezik %s...','Removing untranslated dictionary strings where translation is available for language %s...'=>'Uklanjanje neprevedenih nizova rječnika gdje je prijevod dostupan za jezik %s...','Inserting original strings for language %s...'=>'Umetanje izvornih nizova za jezik %s...','Cleaning original strings table for language %s...'=>'Čišćenje originalne tablice nizova za jezik %s...','Updating original string ids for language %s...'=>'Ažuriranje izvornih ID-ova nizova za jezik %s...','Regenerating original meta table for language %s...'=>'Regeneriranje izvorne meta tablice za jezik %s...','Cleaning original meta table for language %s...'=>'Čišćenje izvorne meta tablice za jezik %s...','Replacing original id NULL with value for language %s...'=>'Zamjena izvornog id NULL s vrijednošću za jezik %s...','Inserting gettext original strings for language %s...'=>'Umetanje izvornih nizova gettext za jezik %s...','Cleaning gettext original strings table for language %s...'=>'Čišćenje tablice izvornih nizova gettext za jezik %s...','Updating gettext original string ids for language %s...'=>'Ažuriranje gettext originalnih ID-ova niza za jezik %s...','Starting gettext database optimization in the background...'=>'Pokretanje optimizacije gettext baze podataka u pozadini...','Migrating taxonomy and post type base slugs to new table structure...'=>'Migracija taksonomije i baznih puževa posta u novu strukturu tablice...','Migrating post slugs to new table structure for language %s...'=>'Migracija postova u novu strukturu tablice za jezik %s...','Migrating term slugs to new table structure for language %s...'=>'Migracija pojma slugovi u novu strukturu tablice za jezik %s...','Finishing up...'=>'Završavam...','TranslatePress needs to optimize gettext database tables. Translations continue to work while this runs in the background.'=>'TranslatePress mora optimizirati tablice gettext baze podataka. Prijevodi će i dalje raditi dok se ovo izvršava u pozadini.','Before starting, we strongly recommend creating a database backup.'=>'Prije pokretanja, snažno preporučujemo da napravite sigurnosnu kopiju baze podataka.','Start optimization'=>'Započni optimizaciju','Update aborted! Could not schedule gettext database optimization.'=>'Ažuriranje prekinuto! Nije bilo moguće zakazati optimizaciju Gettext baze podataka.','Database optimization did not complete successfully. We recommend restoring the original database or <a href="%s" >trying again.</a>'=>'Optimizacija baze podataka nije uspješno završena. Preporučamo vraćanje izvorne baze podataka ili <a href="%s" >pokušajte ponovo.</a>','Update aborted! Your user account doesn\'t have the capability to perform database updates.'=>'Ažuriranje prekinuto! Vaš korisnički račun nema mogućnost izvršavanja ažuriranja baze podataka.','Update aborted! Invalid nonce.'=>'Ažuriranje prekinuto! Nevaljan nonce.','Back to TranslatePress Settings'=>'Povratak na TranslatePress postavke','Successfully updated database!'=>'Baza podataka je uspješno ažurirana!','Updating database to version %s+'=>'Ažuriranje baze podataka na verziju %s+','Processing table for language %s...'=>'Obrada tablice za jezik %s...','Update aborted! Incorrect action.'=>'Ažuriranje prekinuto! Neispravna radnja.','Update aborted! Start the gettext database optimization separately from the Advanced settings page.'=>'Ažuriranje prekinuto! Pokrenite optimizaciju Gettext baze podataka odvojeno sa stranice naprednih postavki.','Update aborted! Incorrect language code.'=>'Ažuriranje prekinuto! Neispravan jezični kod.',' done.'=>' učinjeno.','Update aborted while %1$s. SQL error: %2$s'=>'Ažuriranje prekinuto dok je u tijeku %1$s. SQL greška: %2$s','inserting original strings'=>'Ubacivanje izvornih nizova','checking original string insertion progress'=>'Provjera napretka ubacivanja izvornih nizova','cleaning duplicate original strings'=>'Čišćenje duplikata izvornih nizova','updating original string IDs'=>'Ažuriranje ID-ova izvornih nizova','checking original string ID update progress'=>'Provjera napretka ažuriranja ID-ova izvornih nizova','inserting gettext original strings'=>'Ubacivanje izvornih Gettext nizova','checking gettext original insertion progress'=>'Provjera napretka ubacivanja izvornih Gettext nizova','cleaning duplicate gettext original strings'=>'Čišćenje duplikata izvornih Gettext nizova','updating gettext original string IDs'=>'Ažuriranje ID-ova izvornih Gettext nizova','checking gettext original string ID update progress'=>'Provjera napretka ažuriranja ID-ova izvornih Gettext nizova','All individual TranslatePress add-on plugins <a href="%1$s" target="_blank">have been discontinued</a> and are now included in the premium Personal, Business and Developer versions of TranslatePress. Please log into your <a href="%2$s" target="_blank">account page</a>, download the new premium version and install it. Your individual addons settings will be ported over.'=>'Svi pojedinačni dodaci za dodatke TranslatePress <a href="%1$s" target="_blank"> ukinuti</a> su i sada su uključeni u premium osobne, poslovne i razvojne verzije TranslatePressa. Prijavite se na svoju <a href="%2$s" target="_blank"> stranicu</a>, preuzmite novu premium verziju i instalirajte je. Vaše pojedinačne postavke dodataka bit će prenesene.','Brand-new Language Switcher Settings are here!'=>'Potpuno nove postavke izmjenjivač jezika su ovdje!','Explore pre-made templates, switch colors, flag styles, spacing, layouts & more. Use the live preview to perfect your switcher in seconds.'=>'Istražite unaprijed izrađene predloške, promijenite boje, stilove zastavica, razmak, izglede i još mnogo toga. Upotrijebite pregled uživo kako biste usavršili svoj izmjenjivač u nekoliko sekundi.','Start customizing'=>'Počnite prilagođavati','Read documentation'=>'Pročitajte dokumentaciju','<strong>TranslatePress</strong> requires <strong><a href="http://php.net/manual/en/book.mbstring.php">Multibyte String PHP library</a></strong>. Please contact your server administrator to install it on your server.'=>'<strong>TranslatePress</strong> zahtijeva <strong><a href="http://php.net/manual/en/book.mbstring.php">Multibyte String PHP biblioteku</a></strong>. Obratite se administratoru poslužitelja kako biste ga instalirali na svoj poslužitelj.','Detected long query limitation on WPEngine hosting. Some large pages may appear untranslated. You can remove limitation by adding the following to your site’s wp-config.php: define( \'WPE_GOVERNOR\', false ); '=>'Otkriveno je dugo ograničenje upita na WPEngine hostingu. Neke velike stranice mogu izgledati neprevedene. Ograničenje možete ukloniti dodavanjem sljedećeg u wp-config.php web stranice: define( \'WPE_GOVERNOR\', false ); ','Custom Language Flag'=>'Zastavica prilagođenog jezika','The Language code of the added custom language is invalid.'=>'Jezični kôd dodanog prilagođenog jezika nije valjan.','The Language code of the added custom language cannot be empty.'=>'Kôd jezika dodanog prilagođenog jezika ne može biti prazan.','The Automatic Translation Code of the added custom language is invalid.'=>'Kôd automatskog prijevoda dodanog prilagođenog jezika nije valjan.','Style'=>'Stil','Use shortcode settings'=>'Koristi postavke za shortcode','Custom'=>'Prilagođeno','Language names'=>'Nazivi jezika','Full names'=>'Puni nazivi','Short names'=>'Kratki nazivi','Hide names'=>'Sakrij nazive','Flag position'=>'Položaj zastavice','Before text'=>'Prije teksta','After text'=>'Nakon teksta','Hide flags'=>'Sakrij zastavice','Open on click'=>'Otvori na klik','Show opposite language'=>'Prikaži suprotan jezik','Size'=>'Veličina','Normal'=>'Normalna','Large'=>'Velika','Flag shape'=>'Oblik zastavice','Rectangle'=>'Pravokutnik','Square'=>'Kvadrat','Rounded'=>'Zaobljeni','Transitions'=>'Prijelazi','Background'=>'Pozadina','Hover background'=>'Pozadina pri lebdenju','Hover text'=>'Tekst pri lebdenju','Border color'=>'Boja obruba','Border width'=>'Širina obruba','Border radius'=>'Polumjer obruba','Flag radius'=>'Polumjer zastavice','Disable the legacy TranslatePress language switcher to use the customizable Elementor widget. <a href="%s" target="_blank" rel="noopener noreferrer">Open language switcher settings</a>.'=>'Onemogućite zastarjeli TranslatePress mijenjač jezika da biste koristili prilagodljivi Elementor widget. <a href="%s" target="_blank" rel="noopener noreferrer">Otvorite postavke mijenjača jezika</a>.','The language switcher inherits styling options from shortcode. <a href="%s" target="_blank" rel="noopener noreferrer">Open shortcode settings</a>.'=>'Mijenjač jezika nasljeđuje stilske opcije od shortcode. <a href="%s" target="_blank" rel="noopener noreferrer">Otvori postavke shortcode</a>.','TranslatePress AI'=>'TranslatePress AI','Your TranslatePress AI API Key is valid.'=>'Vaš TranslatePress AI API ključ je ispravan.','Your TranslatePress AI API Key is invalid.'=>'Vaš TranslatePress AI API ključ je neispravan.','Your TranslatePress AI API Key has expired.'=>'Vaš TranslatePress AI API ključ je istekao.','Activate API Key'=>'Aktiviraj API ključ','Deactivate API Key'=>'Deaktiviraj API ključ','Add a TranslatePress AI API Key'=>'Dodaj TranslatePress AI API ključ','TranslatePress AI API Key'=>'TranslatePress AI API ključ','Manage your TranslatePress AI API Key in your %1$s.'=>'Upravljaj svojim TranslatePress AI API ključem u %1$s.','Don’t have a TranslatePress AI API Key?'=>'Nemaš TranslatePress AI API ključ?','Get a free TranslatePress AI API Key Today'=>'Nabavi besplatan TranslatePress AI API ključ danas','Add your TranslatePress AI API Key'=>'Dodaj svoj TranslatePress AI API ključ','Add your TranslatePress AI API Key to unlock all premium features. Find the TranslatePress AI API Key in your'=>'Dodaj svoj TranslatePress AI API ključ za otključavanje svih premium značajki. Pronađi TranslatePress AI API ključ u svom','Your TranslatePress AI API Key is valid and active.'=>'Vaš TranslatePress AI API ključ je ispravan i aktivan.','Activate TranslatePress AI API Key'=>'Aktiviraj TranslatePress AI API ključ','No Active API Key Detected for this website.'=>'Nije otkriven aktivan API ključ za ovu web-stranicu.','In order to enable Automatic Translation using TranslatePress AI, you need an API key by creating a free account.'=>'Da omogućiš automatsko prevođenje pomoću TranslatePress AI, potreban ti je API ključ stvaranjem besplatnog računa.','Enter your API key'=>'Unesi svoj API ključ','In order to enable Automatic Translation using TranslatePress AI, please enter your API key from'=>'Da omogućiš automatsko prevođenje pomoću TranslatePress AI, unesi svoj API ključ s','API Key'=>'API ključ','No Active TranslatePress AI API Key Detected for this website.'=>'Za ovu web-stranicu nije otkriven aktivni TranslatePress AI API ključ.','Get Your Free TranslatePress AI API Key'=>'Nabavite svoj besplatni TranslatePress AI API ključ','Generate API Key'=>'Generiraj API ključ','You have a valid %s <strong>API Key</strong>.'=>'Imate valjani %s <strong>API ključ</strong>.','Manage your API Key & quota on the %s'=>'Upravljajte svojim API ključem i kvotom na %s','Get a Free AI API Key'=>'Nabavite besplatni AI API ključ','This website is already activated under a free API key. Each website can only use one free API key.'=>'Ova web-stranica je već aktivirana pod besplatnim API ključem. Svaka web-stranica može koristiti samo jedan besplatni API ključ.','This website is already activated under a free API key. Each website can only use one free API key. Please upgrade to a premium plan for more TranslatePress AI words from %1$s your account %2$s.'=>'Ova web-stranica je već aktivirana pod besplatnim API ključem. Svaka web-stranica može koristiti samo jedan besplatni API ključ. Nadogradite na premium plan za više TranslatePress AI riječi s %1$s vašeg računa %2$s.','Debug Data for API Key Checking'=>'Podaci za otklanjanje grešaka pri provjeri API ključa','Debug Data for API Key Activation'=>'Podaci za otklanjanje grešaka pri aktivaciji API ključa','TranslatePress finished replacing the existing translations in your dictionary.'=>'TranslatePress je završio zamjenu postojećih prijevoda u vašem rječniku.','Term (%s)'=>'Pojam (%s)','Translations'=>'Prijevodi','Term added. Glossary terms only affect new automatic translations.'=>'Pojam je dodan. Pojmovi rječnika utječu samo na nove automatske prijevode.','Term updated.'=>'Pojam je ažuriran.','Term deleted.'=>'Pojam je izbrisan.','Are you sure you want to delete this term?'=>'Jeste li sigurni da želite izbrisati ovaj pojam?','Something went wrong. Please try again.'=>'Nešto je pošlo po zlu. Pokušajte ponovno.','Quick Edit'=>'Brzo uređivanje','Edit'=>'Uredi','Delete'=>'Izbriši','Update'=>'Ažuriraj','Cancel'=>'Otkaži','No glossary terms match your search.'=>'Nijedan pojam iz rječnika ne odgovara vašoj pretrazi.','No glossary terms found.'=>'Nije pronađen nijedan pojam iz rječnika.','Could not load glossary terms. Please reload the page.'=>'Učitavanje pojmova rječnika nije uspjelo. Osvježite stranicu.','items'=>'stavke','of'=>'od','First page'=>'Prva stranica','Previous page'=>'Prethodna stranica','Next page'=>'Sljedeća stranica','Last page'=>'Posljednja stranica','The inserted term was found in your existing translations, use the %s to make changes there.'=>'Umetnuti pojam pronađen je u vašim postojećim prijevodima, koristite %s za izmjene u tim prijevodima.','search & replace tool'=>'alat za pretraživanje i zamjenu','Please provide at least one existing translation to replace.'=>'Navedite barem jedan postojeći prijevod za zamjenu.','You are about to bulk edit a potentially large amount of translations. This action cannot be undone. It is recommended to make a backup of the database before completing this action.'=>'Upravo ćete masovno urediti potencijalno veliku količinu prijevoda. Ova se radnja ne može poništiti. Preporučuje se napraviti sigurnosnu kopiju baze podataka prije dovršavanja ove radnje.','Continue with replacing existing translations?'=>'Nastaviti sa zamjenom postojećih prijevoda?','No entries found.'=>'Nije pronađen nijedan unos.','Original'=>'Izvornik','Security check failed. Please reload the page and try again.'=>'Sigurnosna provjera nije uspjela. Osvježite stranicu i pokušajte ponovno.','You do not have permission to do this.'=>'Nemate dopuštenje za ovu radnju.','Please enter the term in the default language.'=>'Unesite pojam na zadanom jeziku.','Please provide at least one translation for the term.'=>'Navedite barem jedan prijevod za pojam.','The term “%s” already exists in the glossary.'=>'Pojam „%s” već postoji u rječniku.','The term you are trying to edit no longer exists. Please reload the page.'=>'Pojam koji pokušavate urediti više ne postoji. Osvježite stranicu.','The term you are trying to delete no longer exists. Please reload the page.'=>'Pojam koji pokušavate izbrisati više ne postoji. Osvježite stranicu.','%1$s: %2$d entry updated'=>'%1$s: %2$d unos ažuriran' . "\0" . '%1$s: %2$d unosa ažurirana' . "\0" . '%1$s: %2$d unosa ažurirano','Replacement complete.'=>'Zamjena dovršena.','This is a large replacement. %d entries were updated now and the rest will finish automatically in the background over the next few minutes.'=>'Ovo je velika zamjena. Upravo je ažurirano %d unosa i ostatak će se automatski dovršiti u pozadini tijekom sljedećih nekoliko minuta.','Google Translate v2'=>'Google Translate v2','Google Translate API Key'=>'Google Translate API ključ','Add your API Key here...'=>'Ovdje dodajte svoj API ključ...','Visit <a href="https://cloud.google.com/docs/authentication/api-keys" target="_blank">this link</a> to see how you can set up an API key, <strong>control API costs</strong> and set HTTP referrer restrictions.'=>'Posjetite <a href="https://cloud.google.com/docs/authentication/api-keys" target="_blank">ovu vezu</a> da biste vidjeli kako možete postaviti API ključ, <strong>kontrolirati troškove API-ja</strong> i postaviti ograničenja HTTP preporuke.','Your HTTP referrer is: %s'=>'Vaš HTTP preporuka je: %s','There was an error with your Google Translate key.'=>'Došlo je do pogreške s ključem Google prevoditelja.','There was an error on the server processing your Google Translate key.'=>'Došlo je do greške na poslužitelju koji obrađuje vaš Google Translate ključ.','Please check your TranslatePress license key.'=>'Provjerite svoj TranslatePress licencni ključ.','Create your Free Account'=>'Kreirajte svoj besplatni račun',' or '=>' ili ','Your free account includes: '=>'Vaš besplatni račun uključuje: ','Access to TranslatePress AI for instant automatic translations'=>'Pristup TranslatePress AI za trenutne automatske prijevode','2000 AI words to translate automatically'=>'2000 AI riječi za automatsko prevođenje','Get more AI Words and unlock all AI features with TranslatePress Pro.'=>'Nabavite više AI riječi i otključajte sve AI značajke s TranslatePress Pro.','Upgrade now'=>'Nadogradite sada','You have a valid %s <strong>license</strong>.'=>'Imate važeću %s <strong>licencu</strong>.',' words remaining. '=>' riječi preostalo. ','Recheck'=>'Ponovna provjera','Rechecking...'=>'Ponovna provjera...','Done.'=>'Učinjeno.','Manage your license & quota on the %s'=>'Upravljajte svojom licencom i kvotom na %s','TranslatePress.com Account Page'=>'TranslatePress.com stranica računa','Advanced Add-ons'=>'Napredni dodaci','These addons extend your translation plugin and are available in the Developer, Business and Personal plans.'=>'Ovi dodaci proširuju vaš dodatak za prevođenje i dostupni su u planovima za razvojne, poslovne i osobne.','SEO Pack'=>'SEO paket','SEO support for page slug, page title, description and Facebook and Twitter social graph information. The HTML lang attribute is properly set.'=>'SEO podrška za slug stranice, naslov stranice, opis i informacije o društvenom grafikonu na Facebooku i Twitteru. HTML jezični atribut je ispravno postavljen.','Multiple Languages'=>'Više jezika','Add as many languages as you need for your project to go global. Publish your language only when all your translations are done.'=>'Dodajte onoliko jezika koliko vam je potrebno da bi vaš projekt postao globalan. Objavite svoj jezik tek kada su svi prijevodi gotovi.','Pro Add-ons'=>'Pro dodaci','These addons extend your translation plugin and are available in the Business and Developer plans.'=>'Ovi dodaci proširuju vaš dodatak za prevođenje i dostupni su u planovima za poslovne i razvojne programere.','DeepL Automatic Translation'=>'DeepL automatski prijevod','Automatically translate your website through the DeepL API.'=>'Automatski prevedite svoju web stranicu putem DeepL API-ja.','Prompts visitors to switch to their preferred language based on their browser settings or IP address and remembers the last visited language.'=>'Traži od posjetitelja da se prebace na željeni jezik na temelju postavki preglednika ili IP adrese i pamti posljednji posjećeni jezik.','Translator Accounts'=>'Računi prevoditelja','Create translator accounts for new users or allow existing users that are not administrators to translate your website.'=>'Stvorite račune prevoditelja za nove korisnike ili dopustite postojećim korisnicima koji nisu administratori da prevedu vaše web-mjesto.','Browse As User Role'=>'Pretraživanje kao korisnička uloga','Navigate your website just like a particular user role would. Really useful for dynamic content or hidden content that appears for particular users.'=>'Krećite se svojom web stranicom baš kao što bi to učinila određena korisnička uloga. Stvarno korisno za dinamički sadržaj ili skriveni sadržaj koji se pojavljuje za određene korisnike.','Navigation Based on Language'=>'Navigacija na temelju jezika','Configure different menu items for different languages.'=>'Konfigurirajte različite stavke izbornika za različite jezike.','Connect separate domains or subdomains to each of your translated versions. Strengthen your brand’s local identity and boost SEO performance for every language you support.'=>'Povežite zasebne domene ili poddomene sa svakom od vaših prevedenih verzija. Ojačajte lokalni identitet svog brenda i poboljšajte SEO performanse za svaki jezik koji podržavate.','Enable Modules'=>'Omogući module','Enable Add-on modules to extend TranslatePress and enhance the functionality of your translated site.'=>'Omogućite dodatne module kako biste proširili TranslatePress i poboljšali funkcionalnost svoje prevedene stranice.','TranslatePress Pro is active. Activate your license key to unlock the Pro add-ons below.'=>'TranslatePress Pro je aktivan. Aktivirajte licencni ključ kako biste otključali Pro dodatke u nastavku.','Activate license'=>'Aktiviraj licencu','TranslatePress Pro is installed but not activated yet.'=>'TranslatePress Pro je instaliran, ali još nije aktiviran.','Opens your Plugins page (filtered to TranslatePress) in a new tab. Activate the TranslatePress Pro plugin there, then return to this tab — it will update automatically.'=>'Otvara stranicu Dodaci (filtrirano za TranslatePress) u novoj kartici. Aktivirajte dodatak TranslatePress Pro tamo, a zatim se vratite na ovu karticu — ažurirat će se automatski.','Activate TranslatePress Pro ↗'=>'Aktiviraj TranslatePress Pro ↗','More functionality with TranslatePress Pro.'=>'Više funkcionalnosti uz TranslatePress Pro.','Upgrade now ↗'=>'Nadogradite sada ↗','Already a Pro User?'=>'Već ste profesionalni korisnik?','Opens the WordPress “Add Plugins” page in a new tab. Upload and activate the TranslatePress Pro plugin there, then return to this tab — it will update automatically.'=>'Otvara WordPress stranicu „Dodaj dodatke“ u novoj kartici. Tamo učitajte i aktivirajte dodatak TranslatePress Pro, a zatim se vratite na ovu karticu — ažurirat će se automatski.','Install TranslatePress Pro'=>'Instaliraj TranslatePress Pro','This add-on is not available on your current plan.'=>'Ovaj dodatak nije dostupan na vašem trenutnom planu.','Continue'=>'Nastavi','The link you followed has expired. Please reload the page and try again.'=>'Veza koju ste slijedili je istekla. Ponovno učitajte stranicu i pokušajte ponovno.','Your license key is disabled for this URL. Re-enable it from <a target="_blank" href="https://translatepress.com/account/?utm_source=tp-onboarding&utm_medium=client-site&utm_campaign=activate-license">https://translatepress.com/account</a> -> Manage Sites.'=>'Vaš licenčni ključ je onemogućen za ovaj URL. Ponovno ga omogućite iz <a target="_blank" href="https://translatepress.com/account/?utm_source=tp-onboarding&utm_medium=client-site&utm_campaign=activate-license">https://translatepress.com/account</a> -> Upravljanje stranicama.','<p><strong>License key mismatch.</strong> The license you entered doesn\'t match the TranslatePress version you have installed.</p><p>Please check that you\'ve installed the correct version for your license from your TranslatePress account.</p>'=>'<p><strong>Nepodudaranje licenčnog ključa.</strong> Licenca koju ste unijeli ne odgovara verziji TranslatePressa koju ste instalirali.</p><p>Provjerite jeste li instalirali ispravnu verziju za svoju licencu sa svog TranslatePress računa.</p>','TranslatePress Account'=>'TranslatePress račun','« Go Back'=>'« Vrati se','Your license key is disabled for this URL. Re-enable it from <a target="_blank" href="https://translatepress.com/account/?utm_source=tp-onboarding&utm_medium=client-site&utm_campaign=tp-ai">https://translatepress.com/account</a> -> Manage Sites.'=>'Vaš licenčni ključ je onemogućen za ovaj URL. Ponovno ga omogućite iz <a target="_blank" href="https://translatepress.com/account/?utm_source=tp-onboarding&utm_medium=client-site&utm_campaign=tp-ai">https://translatepress.com/account</a> -> Upravljanje stranicama.','Automatically translate your website using TranslatePress AI.'=>'Automatski prevedite svoju web stranicu pomoću TranslatePress AI.','your account.'=>'vaš račun.','Skip and continue with manual translation »'=>'Preskočite i nastavite s ručnim prijevodom »','Creating a free account includes: '=>'Stvaranje besplatnog računa uključuje: ','Are you a TranslatePress PRO user?'=>'Jeste li korisnik TranslatePress PRO?','Install TranslatePress Pro.'=>'Instaliraj TranslatePress Pro.','Skip this step'=>'Preskoči ovaj korak','The email address you added is incorrect.'=>'Adresa e-pošte koju ste dodali nije točna.','Setup Complete'=>'Postavljanje dovršeno','You\'re ready to start translating!'=>'Spremni ste za početak prevođenja!','You have successfully set up TranslatePress for your website.'=>'Uspješno ste postavili TranslatePress za svoju web stranicu.','Receive '=>'Primi ','Yes, send me multilingual growth tips.'=>'Da, šaljite mi savjete za rast na više jezika.','Start translating'=>'Počnite prevoditi','Sign Up and Start translating'=>'Prijavite se i počnite prevoditi','You need to select a default language.'=>'Trebate odabrati zadani jezik.','You are trying to add an invalid default language. Please select a valid option.'=>'Pokušavate dodati nevažeći zadani jezik. Odaberite valjanu opciju.','Please add an additional language.'=>'Dodajte dodatni jezik.','You are trying to add an invalid additional language. Please select a valid option.'=>'Pokušavate dodati nevažeći dodatni jezik. Odaberite valjanu opciju.','Configure Site Languages'=>'Konfiguriranje jezika stranice','Select the default and additional languages for your website.'=>'Odaberite zadani i dodatni jezik za svoju web stranicu.','You can edit your site languages at any point.'=>'Jezike vaše stranice možete urediti u bilo kojem trenutku.','Default Language'=>'Zadani jezik','Select the language your content is written in.'=>'Odaberite jezik na kojem je vaš sadržaj napisan.','Additional Language'=>'Dodatni jezik','Choose a secondary language...'=>'Odaberite sekundarni jezik...','Slug'=>'Slug','Add Language'=>'Dodavanje jezika','Choose a language...'=>'Odaberite jezik...','TranslatePress Pro is active. Activate your license key to add more languages.'=>'TranslatePress Pro je aktivan. Aktivirajte licencni ključ kako biste dodali više jezika.','Add more than two languages with TranslatePress Pro.'=>'Dodajte više od dva jezika pomoću TranslatePress Pro.','Set up Language Switcher'=>'Postavljanje izmjenjivača jezika','Select the style of the language switcher. You will find more ways to display it, in plugin settings.'=>'Odaberite stil izmjenjivača jezika. Pronaći ćete više načina za prikaz u postavkama dodatka.','Displays a small language drop-down across your website, in a corner of your choosing.'=>'Prikazuje mali padajući izbornik jezika na vašoj web stranici, u kutu po vašem izboru.','Switcher Location'=>'Izmjenjivač jezika','Apply a Template'=>'Primjeni predlžak','You can customize the design later'=>'Dizajn možete prilagoditi kasnije','Default Template'=>'Zadani predložak','Default'=>'Zadano','Dark Template'=>'Tamni predložak','Border Template'=>'Predložak ruba','Border'=>'Rub','Transparent Template'=>'Prozirni predložak','Transparent'=>'Transparentno','Welcome to TranslatePress'=>'Dobrodošli u TranslatePress','Quick guided setup to configure TranslatePress in no time!'=>'Brzo vođeno postavljanje za konfiguriranje TranslatePressa u tren oka!','It takes less than a minute.'=>'Potrebno je manje od minute.','Scanning item %1$d of %2$d...'=>'Skeniranje predmeta %1$d od %2$d...','Manually translated'=>'Ručno prevedeno','Automatically translated'=>'Automatski prevedeno','Gettext file translation'=>'Prijevod Gettext datoteka','Not translated'=>'Nije prevedeno','Bulk Actions'=>'Skupne radnje','Delete entries'=>'Brisanje unosa','Filter'=>'Filtar','Clear filters'=>'Očisti filtre','Language'=>'Jezik','Add New'=>'Dodaj novo','Rescan plugins and theme for strings'=>'Ponovno skenirajte dodatke i temu za nizove','Scanning plugins and theme for strings...'=>'Skeniram dodatke i teme za nizove...','Plugins and theme scan is complete'=>'Skeniranje dodataka i tema je dovršeno','Plugins and theme scan did not finish due to an error'=>'Dodaci i skeniranje teme nisu dovršeni zbog greške','Import / Export'=>'Uvoz / izvoz','See More'=>'Vidi više','See Less'=>'Vidi manje','Apply'=>'Primijeni','No strings match your query.'=>'Nijedan niz ne odgovara vašem upitu.','Try to rescan plugins and theme for strings.'=>'Pokušajte ponovno skenirati dodatke i temu za nizove.','An error occurred while loading results. Most likely you were logged out. Reload page?'=>'Došlo je do pogreške tijekom učitavanja rezultata. Najvjerojatnije ste bili odjavljeni. Ponovno učitavanje stranice?','found in translation'=>'pronađeno u prijevodu','Select All'=>'Odaberi sve','Select Visible'=>'Odaberite vidljivo','You are about to perform this action on all the strings matching your filter, not just the visibly checked. To perform the action only to the visible strings click "Select Visible" from the table header dropdown.'=>'Spremate se izvršiti ovu radnju na svim nizovima koji odgovaraju vašem filtru, a ne samo na vidljivo označenim. Da biste radnju izvršili samo na vidljivim nizovima, kliknite "Odaberi vidljivo" na padajućem izborniku zaglavlja tablice.','You are about to perform this action only on the visible strings. To perform the action on all the strings matching the filter click "Select All" from the table header dropdown.'=>'Ovu ćete radnju izvesti samo na vidljivim nizovima. Da biste izvršili radnju na svim nizovima koji odgovaraju filtru, kliknite "Odaberi sve" na padajućem izborniku zaglavlja tablice.','To continue please type the word:'=>'Za nastavak upišite riječ:','The word typed was incorrect. Action was cancelled.'=>'Otipkana riječ bila je netočna. Akcija je otkazana.','Warning: This action cannot be undone. Deleting a string will remove its current translation. The original string will appear again in this interface after TranslatePress detects it. This action is NOT equivalent to excluding the string from being translated again.'=>'Upozorenje: Ova se akcija ne može poništiti. Brisanjem niza uklonit će se njegov trenutni prijevod. Izvorni niz ponovno će se pojaviti u ovom sučelju nakon što ga TranslatePress otkrije. Ova radnja NIJE ekvivalentna isključivanju niza iz ponovnog prevođenja.','%d original entries and their translations were deleted.'=>'%d izvorni unosi i njihovi prijevodi su izbrisani.','Navigate to next page'=>'Idite na sljedeću stranicu','Navigate to previous page'=>'Idite na prethodnu stranicu','Navigate to first page'=>'Navigacija na prvu stranicu','Navigate to last page'=>'Idite na zadnju stranicu','Type a page number to navigate to'=>'Upišite broj stranice na koju želite prijeći','Incorrect page number. Type a page number between 1 and total number of pages'=>'Netočan broj stranice. Upišite broj stranice između 1 i ukupnog broja stranica','Search original and translated strings containing typed keywords while also matching selected filters. Place string in quotes for exact match: "string"'=>'Pretražujte izvorne i prevedene nizove koji sadrže tipizirane ključne riječi, dok istovremeno usklađujete odabrane filtre. Stavite string u navodnike za točno podudaranje: "string"','Filter strings according to selected translation status, filters and keywords and selected filters'=>'Filtrirajte nizove prema odabranom statusu prijevoda, filtrima i ključnim riječima te odabranim filtrima','Removes selected filters'=>'Uklanja odabrane filtre','See options for selecting all strings'=>'Pogledajte opcije za odabir svih nizova','Click to sort strings by this column'=>'Kliknite za sortiranje nizova prema ovom stupcu','The ID of the WordPress post where this string was detected. Empty if the string is not associated with a specific post.'=>'ID WordPress objave u kojoj je ovaj niz otkriven. Prazno ako niz nije povezan s određenom objavom.','Language in which the translation status filter applies. Leave unselected for the translation status to apply to ANY language'=>'Jezik na kojem se primjenjuje filtar statusa prijevoda. Ostavite neodabrano za status prijevoda kako bi se primijenio na BILO KOJI jezik','Search'=>'Pretraživanje','Slugs that are not found in either one of the other categories.'=>'Slugovi koji se ne nalaze ni u jednoj od drugih kategorija.','Plugins and Theme String Translation'=>'Dodaci i prijevod niza tema','Gettext'=>'Gettext','Search Gettext Strings'=>'Pretraži Gettext nizove','Original String'=>'Izvorni niz','Filter by domain'=>'Filtriraj prema domeni','Filter by type'=>'Filtriraj prema vrsti','Email text'=>'Tekst e-pošte','Emails String Translation'=>'Prijevod niza e-pošte','Emails'=>'E-pošta','Search Email Strings'=>'Pretraživanje nizova e-pošte','User Inputted String Translation'=>'Prijevod niza koji je unio korisnik','Regular'=>'Uobičajeno','Search Regular Strings'=>'Pretraživanje običnih nizova','Filter by Translation Block'=>'Filtriraj prema bloku prijevoda','String Translation Editor'=>'Uređivač prijevoda nizova','Every minute'=>'Svake minute','Could not load the background task.'=>'Učitavanje pozadinskog zadatka nije uspjelo.','Waiting to start background processing...'=>'Čeka se pokretanje pozadinske obrade...','Background processing could not start.'=>'Pozadinska obrada nije mogla započeti.','Background processing completed.'=>'Pozadinska obrada dovršena.','A previous batch item failed.'=>'Prethodna stavka serije nije uspjela.','TranslatePress background processing did not complete successfully.'=>'Pozadinska obrada TranslatePressa nije uspješno dovršena.','Error: %s'=>'Greška: %s','You do not have permission to view this task status.'=>'Nemate dopuštenje za pregled statusa ovog zadatka.','Invalid batch task.'=>'Nevažeći batch zadatak.','TranslatePress is processing a background task.'=>'TranslatePress obrađuje zadatak u pozadini.','TranslatePress background processing completed successfully.'=>'Pozadinska obrada TranslatePressa uspješno je dovršena.','Processing %s...'=>'Obrada %s...','%s is optimizing gettext database tables in the background. Translations continue to work while this runs.'=>'%s optimizira tablice gettext baze podataka u pozadini. Prijevodi i dalje funkcioniraju tijekom izvršavanja.','TranslatePress gettext database optimization completed successfully.'=>'Optimizacija gettext baze podataka TranslatePressa uspješno je dovršena.','TranslatePress has detected and cleaned up some failed translation entries in your database following %s. No further action is required.'=>'TranslatePress je otkrio i očistio neke neuspjele prijevodne zapise u vašoj bazi podataka nakon %s. Nije potrebna daljnja radnja.','an isolated incident'=>'izoliranog incidenta','Update aborted! Unknown gettext lookup hash migration phase: %s.'=>'Ažuriranje prekinuto! Nepoznata faza migracije hasha za pretraživanje gettexta: %s.','Update aborted! Could not find an available gettext original_id index name for table %s.'=>'Ažuriranje prekinuto! Nije moguće pronaći dostupno ime indeksa original_id gettexta za tablicu %s.','Update aborted! Gettext lookup hash migration cannot process invalid ID %1$d in table %2$s. Repair the table ID schema and retry.'=>'Ažuriranje prekinuto! Migracija hasha za pretraživanje gettexta ne može obraditi nevažeći ID %1$d u tablici %2$s. Popravite shemu ID-a tablice i pokušajte ponovno.','Update aborted! Table %1$s still references %2$d duplicate gettext original ids.'=>'Ažuriranje prekinuto! Tablica %1$s i dalje referencira %2$d duplikata originalnih ID-ova gettexta.','Update aborted! Gettext original meta still references %d duplicate original ids.'=>'Ažuriranje prekinuto! Meta podaci originala gettexta i dalje referenciraju %d duplikata originalnih ID-ova.','Gettext database optimization completed.'=>'Optimizacija gettext baze podataka dovršena.','Deduplicating gettext translation tables...'=>'Uklanjanje duplikata iz tablica prijevoda gettexta...','Migrating gettext original lookup hashes...'=>'Migracija hasha za pretraživanje originala gettexta...','Preparing the gettext originals lookup index...'=>'Priprema indeksa za pretraživanje originala gettexta...','Updating gettext runtime statuses...'=>'Ažuriranje gettext statusa izvođenja...','Finishing gettext database optimization...'=>'Dovršavanje optimizacije gettext baze podataka...','Updating gettext runtime statuses for language %s...'=>'Ažuriranje gettext statusa izvođenja za jezik %s...','Resolving missing gettext original ids in %s...'=>'Rješavanje nedostajućih gettext originalnih ID-ova u %s...','Preparing gettext table %s...'=>'Priprema gettext tablice %s...','Removing invalid gettext rows from %s...'=>'Uklanjanje nevažećih gettext redaka iz %s...','Prepared gettext original ids in %s...'=>'Pripremljeni gettext originalni ID-ovi u %s...','Normalizing plural forms in %s...'=>'Normalizacija množinskih oblika u %s...','Processing duplicate gettext rows in %s...'=>'Obrada duplikatnih gettext redaka u %s...','Building duplicate gettext map for %s...'=>'Izgradnja mape duplikatnih gettext redaka za %s...','Verifying gettext table %s...'=>'Provjera gettext tablice %s...','Deleting duplicate gettext rows from %s...'=>'Brisanje duplikatnih gettext redaka iz %s...','Rechecking duplicate gettext rows in %s...'=>'Ponovna provjera duplikatnih gettext redaka u %s...','Adding unique gettext index for %s...'=>'Dodavanje jedinstvenog gettext indeksa za %s...','Finished gettext table %s.'=>'Završena gettext tablica %s.','License'=>'Licenca','Your License Key is valid.'=>'Vaš licencni ključ je valjan.','Your License Key is invalid.'=>'Vaš licencni ključ nije važeći.','Your License has expired.'=>'Vaša licenca je istekla.','Deactivate License'=>'Deaktiviraj licencu','Add a license key'=>'Dodavanje licenčnog ključa','License Key'=>'Licencni ključ','Manage your license in your %1$s.'=>'Upravljajte svojom licencom u svojim %1$s.','Don’t have a TranslatePress AI License Key?'=>'Nemate licencni ključ za TranslatePress AI?','Get a free License Today'=>'Nabavite besplatnu licencu već danas','Add your License Key'=>'Dodajte svoj licenčni ključ','Add your License Key to unlock all premium features. Find the License Key in your'=>'Dodajte svoj licenčni ključ za otključavanje svih premium značajki. Pronađite licenčni ključ u svom','Your license is valid and active.'=>'Vaša licenca je važeća i aktivna.','TranslatePress License'=>'Licenca za TranslatePress','In order to enable Automatic Translation using TranslatePress AI, you need a license key by creating a free account.'=>'Da biste omogućili automatski prijevod pomoću TranslatePress AI, potreban vam je licencni ključ stvaranjem besplatnog računa.','In order to enable Automatic Translation using TranslatePress AI, please enter your license key from'=>'Da biste omogućili automatsko prevođenje pomoću TranslatePress AI, unesite svoj licencni ključ iz','Get Your Free TranslatePress AI License'=>'Nabavite besplatnu TranslatePress AI licencu','Generate License'=>'Generiraj licencu','Get a Free AI License'=>'Nabavite besplatnu AI licencu','This website is already activated under a free license. Each website can only use one free license.'=>'Ova web stranica je već aktivirana pod besplatnom licencom. Svaka web stranica može koristiti samo jednu besplatnu licencu.','This website is already activated under a free license. Each website can only use one free license. Please upgrade to a premium plan for more TranslatePress AI words from %1$s your account %2$s.'=>'Ova web stranica je već aktivirana pod besplatnom licencom. Svaka web stranica može koristiti samo jednu besplatnu licencu. Nadogradite na premium plan za više riječi TranslatePress AI s %1$s svog računa %2$s.','Debug Data for License Checking'=>'Otklanjanje pogrešaka podataka za provjeru licence','Debug Data for License Activation'=>'Otklanjanje pogrešaka podataka za aktivaciju licence','Please install and activate the TranslatePress - Multilingual plugin'=>'Instalirajte i aktivirajte TranslatePress - višejezični dodatak','Please update the TranslatePress - Multilingual plugin to version %1$s or higher to ensure %2$s functions correctly.'=>'Ažurirajte dodatak TranslatePress - Multilingual na verziju %1$s ili noviju kako biste osigurali ispravan rad %2$s.','Please update TranslatePress - Multilingual to version %2$s or newer. Your currently installed version of TranslatePress - Multilingual is no longer compatible with the current version of %1$s.'=>'Ažurirajte TranslatePress - Multilingual na verziju %2$s ili noviju. Trenutno instalirana verzija dodatka TranslatePress - Multilingual više nije kompatibilna s trenutnom verzijom %1$s.','All TranslatePress functionalities are disabled until then.'=>'Sve funkcionalnosti TranslatePressa su do tada onemogućene.','Update Now'=>'Ažuriraj','This TranslatePress add-on has been migrated to the main plugin and is no longer used. You can delete it.'=>'Ovaj dodatak za TranslatePress premješten je u glavni dodatak i više se ne koristi. Možete ga izbrisati.','<strong>TranslatePress</strong> requires at least PHP version 5.6.20+ to run. It is the <a href="%s">minimum requirement of the latest WordPress version</a>. Please contact your server administrator to update your PHP version.'=>'<strong>TranslatePress</strong> zahtijeva najmanje PHP verziju 5.6.20+ za rad. To je <a href="%s">minimalni zahtjev za najnoviju verziju WordPressa</a>. Obratite se svom administratoru poslužitelja da ažurira svoju verziju PHP-a.','TranslatePress Add-ons'=>'TranslatePress dodaci','You must first purchase this version to have access to the addon %1$shere%2$s'=>'Prvo morate kupiti ovu verziju da biste imali pristup dodatku %1$shere%2$s','You need an active license to have access to the addon. Renew or purchase a new one %1$shere%2$s.'=>'Potrebna vam je aktivna licenca da biste imali pristup dodatku. Obnovite ili kupite novu %1$sovdje%2$s.','Please %1$senter your license%2$s key first, to activate this addon.'=>'Prvo %1$sunesite svoj licencni%2$s ključ za aktiviranje ovog dodatka.','SEO Pack (Legacy)'=>'SEO paket (naslijeđe)','SEO support for page slug, page title, description and facebook and twitter social graph information. The HTML lang attribute is properly set.'=>'SEO podrška za slug stranice, naslov stranice, opis i informacije o društvenom grafikonu na Facebooku i Twitteru. Atribut HTML lang ispravno je postavljen.','Recommended Plugins'=>'Preporučeni dodaci','A short list of plugins you can use to extend your website.'=>'Kratki popis dodataka koje možete koristiti za proširenje svoje web stranice.','Profile Builder'=>'Graditelj profila','Capture more user information on the registration form with the help of Profile Builder\'s custom user profile fields and/or add an Email Confirmation process to verify your customers accounts.'=>'Snimite više korisničkih podataka na obrascu za registraciju uz pomoć prilagođenih polja korisničkog profila Profile Buildera i/ili dodajte postupak potvrde e-pošte kako biste potvrdili svoje korisničke račune.','Paid Member Subscriptions'=>'Paid Member Subscriptions','Accept user payments, create subscription plans and restrict content on your membership site.'=>'Prihvaćajte korisnička plaćanja, izradite planove pretplate i ograničite sadržaj na svojoj stranici za članstvo.','WP Webhooks Automator'=>'WP Webhooks Automator','Create no-code automations and workflows on your WordPress site. Easily connect your plugins, sites and apps together.'=>'Stvorite automatizaciju i tijekove rada bez koda na svojoj WordPress stranici. Jednostavno povežite svoje dodatke, web stranice i aplikacije.','Save Changes'=>'Spremi promjene','Account Page'=>'Stranica računa','You can get one for %1$sfree%2$s, by creating a free account. It includes:'=>'Možete ga dobiti %1$sbesplatno%2$s, stvaranjem besplatnog računa. Uključuje:','Debug Information'=>'Informacije o otklanjanju pogrešaka','Get more AI words and unlock all features with TranslatePress Pro.'=>'Nabavite više AI riječi i otključajte sve značajke uz TranslatePress Pro.','Already purchased a Premium version?'=>'Već ste kupili Premium verziju?','Go to your %1$s'=>'Idite na svoj %1$s','TranslatePress.com Account'=>'TranslatePress.com račun','Download & Install the Pro plugin'=>'Preuzmite i instalirajte Pro dodatak','Learn More'=>'Uči više','TranslatePress Errors'=>'Pogreške TranslatePress','There are no logged errors.'=>'Nema zabilježenih grešaka.','WordPress Translation Plugin'=>'WordPress dodatak za prevođenje','Back to Glossary'=>'Natrag na rječnik','Search Existing Translations'=>'Pretraži postojeće prijevode','Search the existing dictionary entries to see how a term is currently translated in each language.'=>'Pretražite postojeće unose rječnika da biste vidjeli kako je pojam trenutačno preveden na svakom jeziku.','To fully explore all the translations, use %s.'=>'Da biste u potpunosti istražili sve prijevode, koristite %s.','Search existing translations'=>'Pretraži postojeće prijevode','Replace Existing Translations'=>'Zamijeni postojeće prijevode','The requested glossary term could not be found. It may have been deleted.'=>'Traženi pojam glosara nije pronađen. Možda je obrisan.','&laquo; Back to Glossary'=>'&laquo; Natrag na glosar','For each language, enter the current (existing) translation you want to find; every case-insensitive occurrence in the stored translations will be replaced with the new translation, keeping the original capitalization.'=>'Za svaki jezik unesite trenutni (postojeći) prijevod koji želite pronaći; svako pojavljivanje u spremljenim prijevodima bit će zamijenjeno novim prijevodom bez obzira na velika i mala slova, zadržavajući izvornu kapitalizaciju.','Leaving a language field empty will skip that language entirely (no changes will be made for it). Only one existing translation per language can be entered at a time. If you have multiple translations to replace for the same language, simply run the replacement again with the next value.'=>'Ako ostavite polje za jezik prazno, taj će jezik biti u potpunosti preskočen (neće biti izvršene nikakve promjene). Istovremeno se može unijeti samo jedan postojeći prijevod po jeziku. Ako imate više prijevoda za zamjenu na istom jeziku, jednostavno ponovno pokrenite zamjenu sa sljedećom vrijednošću.','The "Existing translation" is not the term in the default language, but rather the already existing wrong translation you want to correct.'=>'"Postojeći prijevod" nije pojam na zadanom jeziku, već već postojeći pogrešan prijevod koji želite ispraviti.','Existing translation'=>'Postojeći prijevod','New translation'=>'Novi prijevod','Replace in existing translations'=>'Zamijeni u postojećim prijevodima','Glossary is available only with the TranslatePress AI engine.'=>'Glosar je dostupan samo s TranslatePress AI motorom.','Select the %s automatic translation engine to add and manage glossary terms. For other translation engines (such as DeepL or Google Translate), glossary functions are available in the translation provider’s dashboard.'=>'Odaberite automatski prijevodni motor %s za dodavanje i upravljanje pojmovima glosara. Za druge prijevodne motore (kao što su DeepL ili Google Translate), funkcije glosara dostupne su na nadzornoj ploči pružatelja usluga.','Add Glossary Term'=>'Dodaj pojam glosara','Define words or phrases that should not be translated automatically, and optionally provide replacements per language.'=>'Definirajte riječi ili izraze koji se ne smiju automatski prevesti te po želji navedite zamjene po jezicima.','The original word or phrase in the default language.'=>'Izvorna riječ ili izraz na zadanom jeziku.','Add Term'=>'Dodaj pojam','Search glossary terms'=>'Pretraži pojmove glosara','Search terms'=>'Pretraži pojmove','Search Glossary'=>'Pretraži glosar','Loading…'=>'Učitavanje…','To edit existing translations, use the %s.'=>'Za uređivanje postojećih prijevoda upotrijebite %s.','Language Switcher update notice'=>'Obavijest o ažuriranju izmjenjivača jezika','Legacy language switcher is currently enabled'=>'Trenutačno je omogućen naslijeđeni izmjenjivač jezika','We’ve upgraded the switcher for richer customization and a better user experience.<br>In order to use the new configurator, turn off <strong>Load legacy language switcher</strong>.'=>'Nadogradili smo prekidač za bogatiju prilagodbu i bolje korisničko iskustvo.<br>Da biste koristili novi konfigurator, isključite ga <strong>Učitajte naslijeđeni prekidač jezika</strong>.','Note: You can switch back anytime from <strong>Advanced Settings → <a href="%s">Troubleshooting</a></strong>.'=>'Napomena: U bilo kojem trenutku možete se vratiti iz <strong>Naprednih postavki na → <a href="%s">Otklanjanje poteškoća</a></strong>.','Enable the new switcher'=>'Omogućite novi izmjenjivač','Get a translation volume estimate with a detailed breakdown per page'=>'Dobijte procjenu obujma prijevoda s detaljnom razradom po stranici.','Find how many translatable words are on your website'=>'Saznajte koliko prevedivih riječi ima na vašoj web stranici.','<strong>DeepL</strong> automatic translation is available as a <a href="%1$s" target="_blank" title="%2$s">%2$s</a>.'=>'<strong>DeepL</strong> automatski prijevod dostupan je kao <a href="%1$s" target="_blank" title="%2$s">%2$s</a>.','By upgrading you\'ll get access to all paid add-ons, premium support and help fund the future development of TranslatePress.'=>'Nadogradnjom ćete dobiti pristup svim plaćenim dodacima, vrhunsku podršku i pomoći u financiranju budućeg razvoja TranslatePressa.','To use <strong>DeepL</strong> for automatic translation, activate this Pro add-on from the <a href="%1$s" target="_self" title="%2$s">%2$s</a>.'=>'Da biste koristili <strong>DeepL</strong> za automatsko prevođenje, aktivirajte ovaj Pro dodatak iz <a href="%1$s" target="_self" title="%2$s">%2$s</a>.','Please note that DeepL API usage is paid separately. See <a href="https://www.deepl.com/pro.html#developer">DeepL pricing information</a>.'=>'Imajte na umu da se korištenje DeepL API-ja plaća zasebno. Pogledajte <a href="https://www.deepl.com/pro.html#developer">DeepL informacije o cijenama</a>.','TranslatePress Pro Add-ons'=>'TranslatePress Pro dodaci','Test API credentials'=>'Vjerodajnice za testiranje API-ja','Check if the selected translation engine is configured correctly.'=>'Provjerite je li odabrani mehanizam za prevođenje ispravno konfiguriran.','Alternative Engines'=>'Alternativni motori','More info'=>'Više informacija','Switch to TranslatePress AI'=>'Prebacite se na TranslatePress AI','Integrate machine translation directly with your WordPress website.'=>'Integrirajte strojni prijevod izravno sa svojom WordPress web stranicom.','Choose which engine you want to use in order to %1$s automatically translate your website.'=>'Odaberite koji mehanizam želite koristiti kako bi %1$s automatski preveli vašu web stranicu.','Automatically Translate Slugs'=>'Automatski prevedi slugove','Generate automatic translations of slugs for posts, pages and Custom Post Types.<br/>The slugs will be automatically translated starting with the second refresh of each page.'=>'Generirajte automatske prijevode slugova za objave, stranice i prilagođene vrste objava.<br/>Brojevi će se automatski prevesti počevši od drugog osvježavanja svake stranice.','This feature is only available in the paid version. Upgrade TranslatePress and unlock more premium features.'=>'Ova je značajka dostupna samo u plaćenoj verziji. Nadogradite TranslatePress i otključajte više premium značajki.','Requires <a href="%s" title="TranslatePress Add-on SEO Pack documentation" target="_blank">SEO Pack Add-on</a> to be installed and activated.'=>'Zahtijeva <a href="%s" title="TranslatePress Add-on SEO Pack dokumentacija" target="_blank">SEO Pack Add-on</a> za instalaciju i aktivaciju.','Automatic Translation Settings'=>'Postavke automatskog prijevoda','AI Words Low Notification'=>'Obavijest o niskoj razini AI riječi','Receive an email notification when your TranslatePress AI word count drops below the specified threshold.'=>'Primite obavijest e-poštom kada broj TranslatePress AI riječi padne ispod navedenog praga.','This feature is only available when using the TranslatePress AI translation engine.'=>'Ova značajka dostupna je samo kada koristite TranslatePress AI pogon za prijevod.','Notification Email'=>'E-pošta za obavijesti','The email address where the low AI words notification will be sent.'=>'Adresa e-pošte na koju će se slati obavijest o niskoj razini AI riječi.','Word Threshold'=>'Prag riječi','words'=>'riječi','You will be notified when remaining AI words drop below this number.'=>'Bit ćete obaviješteni kada preostale AI riječi padnu ispod ovog broja.','Block Crawlers'=>'Blokirajte indeksatore','Block crawlers from triggering automatic translations on your website.<br>This will not prevent crawlers from accessing this site\'s pages.'=>'Blokirajte alatima za indeksiranje pokretanje automatskih prijevoda na vašoj web stranici. <br>To neće spriječiti alate za indeksiranje da pristupe stranicama ove web stranice.','Limit machine translation / characters per day'=>'Ograničite strojno prevođenje / znakove po danu','Add a limit to the number of automatically translated characters so you can better budget your project.'=>'Dodajte ograničenje broja automatski prevedenih znakova da biste mogli bolje proračunati svoj projekt.','characters per day'=>'znakova po danu','Today\'s Character Count: '=>'Današnji broj znakova: ','Log machine translation queries.'=>'Zabilježite upite za strojno prevođenje.','Only enable for testing purposes. Can impact performance.<br>All records are stored in the wp_trp_machine_translation_log database table. Use a plugin like <a href="https://wordpress.org/plugins/wp-data-access/" target="_blank">WP Data Access</a> to browse the logs or directly from your database manager (PHPMyAdmin, etc.)'=>'Omogući samo u svrhu testiranja. Može utjecati na performanse. <br>Svi zapisi pohranjuju se u tablicu baze podataka wp_trp_machine_translation_log. Koristite dodatak kao što je <a href="https://wordpress.org/plugins/wp-data-access/" target="_blank">WP Data Access</a> za pregledavanje zapisa ili izravno iz upravitelja baze podataka (PHPMyAdmin, itd.)','Test API Credentials'=>'Testirajte vjerodajnice API-ja','HTTP Referrer: '=>'HTTP preporuka: ','Use this HTTP Referrer if the API lets you restrict key usage from its Dashboard.'=>'Koristite ovu HTTP preporuku ako vam API omogućuje ograničavanje upotrebe ključeva s nadzorne ploče.','Request URL'=>'URL zahtjeva','Request Headers'=>'Zaglavlja zahtjeva','Request Body'=>'Tijelo zahtjeva','Response'=>'Odgovor','Response Body'=>'Tijelo odgovora','Entire Response From wp_remote_get():'=>'Cijeli odgovor od wp_remote_get():','Select the languages you wish to make your website available in.'=>'Odaberite jezike na kojima želite učiniti svoju web stranicu dostupnom.','Formality'=>'Formalnost','Code'=>'Kod','Formal'=>'Formalno','Informal'=>'Neformalno','This language does not support formality. '=>'Ovaj jezik ne podržava formalnost. ','Are you sure you want to remove this language?'=>'Jeste li sigurni da želite ukloniti ovaj jezik?','Custom Languages'=>'Prilagođeni jezici','Adding more than two languages is a paid feature. Upgrade TranslatePress and unlock more premium features.'=>'Dodavanje više od dva jezika značajka je koja se plaća. Nadogradite TranslatePress i otključajte više premium značajki.','Please %1$senter your license%2$s key first to add more languages.'=>'Prvo %1$sunesite svoju licencni%2$s ključ da biste dodali više jezika.','You need an active license to add more languages. Verify in your %1$saccount%2$s that your license is valid'=>'Potrebna vam je aktivna licenca za dodavanje više jezika. Na %1$sračunu%2$s provjerite je li vaša licenca valjana','To Add more languages activate the Multiple Languages Addon'=>'Da biste dodali više jezika, aktivirajte dodatak za više jezika','Website Languages'=>'Jezici web stranice','WARNING. Changing the default language will invalidate existing translations.'=>'UPOZORENJE. Promjena standardnog jezika poništit će postojeće prijevode.','Even changing from en_US to en_GB, because they are treated as two different languages.'=>'Čak ako se mijenjaju iz en_US u en_GB, jer se tretiraju kao dva različita jezika.','In most cases changing the default flag is all it is needed: '=>'U većini slučajeva promjena zadane zastavice je sve što je potrebno: ','replace the default flag'=>'zamjeni zadane zastavice','Re-run Setup Wizard'=>'Ponovno pokrenite čarobnjak za postavljanje','The Setup wizard allows you to quickly setup TranslatePress. You can initiate it at any time.'=>'Čarobnjak za postavljanje omogućava vam brzo postavljanje TranslatePressa. Možete ga pokrenuti u bilo kojem trenutku.','Language Settings'=>'Postavke jezika','Use Native language name'=>'Koristite naziv materinjeg jezika','Check if you want to display languages in their native names. Otherwise, languages will be displayed in English.'=>'Provjerite želite li prikazati jezike u njihovim izvornim nazivima. U suprotnom, jezici će biti prikazani na engleskom.','Use a subdirectory for the default language'=>'Korištenje poddirektorija za zadani jezik','Check if you want to add the subdirectory in the URL for the default language.</br>By checking this option, the default language seen by website visitors will become the first one in the "All Languages" list.'=>'Provjerite želite li dodati poddirektorij u URL za zadani jezik.</br>Označavanjem ove opcije, zadani jezik koji vide posjetitelji web stranice postat će prvi na popisu "Svi jezici".','Force language in custom links'=>'Prisilni jezik u prilagođenim vezama','Select Yes if you want to force custom links without language encoding to keep the currently selected language.'=>'Odaberite Da ako želite prisilno prisiliti prilagođene veze bez kodiranja jezika da biste zadržali trenutno odabrani jezik.','Shortcode '=>'Kratki kod ','Use shortcode on any page or widget.'=>'Koristite kratki kod na bilo kojoj stranici ili widgetu.','You can also add the <a href="%s" title="Language Switcher Block Documentation">Language Switcher Block</a> in the WP Gutenberg Editor.'=>'Također možete dodati <a href="%s" title="Dokumentacija o bloku prekidača jezika">Blok prekidača jezika</a> u uredniku WP Gutenberg.','Menu item'=>'Stavka izbornika','Go to  %1$s Appearance -> Menus%2$s to add languages to the Language Switcher in any menu.'=>'Idite na  %1$s Izgled -> Izbornici%2$s za dodavanje jezika u Izmjenjivač jezika u bilo kojem izborniku.','Learn more in our documentation.'=>'Saznajte više u našoj dokumentaciji.','Floating language selection'=>'Plutajući odabir jezika','Add a floating dropdown that follows the user on every page.'=>'Dodajte plutajući padajući izbornik koji prati korisnika na svakoj stranici.','Show "Powered by TranslatePress"'=>'Prikaži "Pokreće TranslatePress"','Show the small "Powered by TranslatePress" label in the floater language switcher.'=>'Prikažite malu oznaku "Pokreće TranslatePress" u prekidaču jezika plutajućeg jezika.','5 Days to Better Multilingual Websites'=>'5 dana do boljih višejezičnih web stranica','%sJoin our FREE & EXCLUSIVE onboarding course%s and learn how to grow your multilingual traffic, reach international markets, and save time & money while getting the most out of TranslatePress!'=>'%sPridružite se našem BESPLATNOM i EKSKLUZIVNOM onboarding tečaju i naučite kako povećati svoj višejezični promet%s doći do međunarodnih tržišta i uštedjeti vrijeme i novac, a istovremeno izvući maksimum iz TranslatePressa!','Invalid email address'=>'Nevažeća adresa e-pošte','Your email'=>'Vaša e-pošta','Sign me up!'=>'Prijavite me!','Sign up with your email address and receive a 5-part email guide to help you maximize the power of TranslatePress.'=>'Prijavite se sa svojom adresom e-pošte i primite 5-dijelni vodič putem e-pošte koji će vam pomoći da maksimalno iskoristite snagu TranslatePressa.','Dismiss email course notification'=>'Odbacivanje obavijesti o tečaju e-poštom','Hey %s,<br>Never miss an important update - opt in to our security and feature updates notifications, and non-sensitive diagnostic tracking.'=>'Nikad %s,<br>ne propustite važno ažuriranje – uključite se u naše obavijesti o sigurnosnim ažuriranjima i ažuriranjima značajki te neosjetljivo dijagnostičko praćenje.','Allow & Continue'=>'Dopusti i nastavi','Skip'=>'Preskoči','This will allow TranslatePress to:'=>'To će omogućiti TranslatePressu da:','Your profile overview'=>'Pregled vašeg profila','Name and email address'=>'Ime i adresa e-pošte','Admin Notices'=>'Obavijesti administratora','Updates, announcements, marketing, no spam'=>'Ažuriranja, najave, marketing, bez neželjene pošte','Plugin status & settings'=>'Status i postavke dodatka','Active, Deactivated, installed version and settings'=>'Aktivna, deaktivirana, instalirana verzija i postavke','Privacy Policy'=>'Politika privatnosti','Terms of Service'=>'Uvjeti pružanja usluge','Support'=>'Podrška','Add Extra AI Words'=>'Dodaj dodatne AI riječi','<strong>IMPORTANT NOTE:</strong> Before performing this action it is strongly recommended to first backup the database.'=>'<strong>VAŽNA NAPOMENA:</strong> Prije izvođenja ove radnje preporučuje se da prvo napravite sigurnosnu kopiju baze podataka.','IMPORTANT: It is strongly recommended to first backup the database!! Are you sure you want to continue?'=>'VAŽNO: Toplo se preporučuje da prvo napravite sigurnosnu kopiju baze podataka!! Jeste li sigurni da želite nastaviti?','Operations to perform'=>'Operacije koje treba izvesti','Remove CDATA for original and dictionary strings'=>'Uklanjanje CDATA za izvorne nizove i nizove rječnika','Removes CDATA from trp_original_strings and trp_dictionary_* tables.<br>This type of content should not be detected by TranslatePress. It might have been introduced in the database in older versions of the plugin.'=>'Uklanja CDATA iz tablica trp_original_strings i trp_dictionary_*. <br>TranslatePress ne bi trebao otkriti ovu vrstu sadržaja. Možda je uveden u bazu podataka u starijim verzijama dodatka.','Remove untranslated links from dictionary tables'=>'Uklanjanje neprevedenih veza iz tablica rječnika','Removes untranslated links and images from all trp_dictionary_* tables. These tables contain translations for user-inputted strings such as post content, post title, menus etc.'=>'Uklanja neprevedene veze i slike iz svih tablica trp_dictionary_*. Ove tablice sadrže prijevode za nizove koje je unio korisnik kao što su sadržaj objave, naslov objave, izbornici itd.','Remove duplicate rows for gettext strings'=>'Uklonite duplicirane retke za gettext nizove','Cleans up all trp_gettext_* tables of duplicate rows. These tables contain translations for themes and plugin strings.'=>'Čisti sve trp_gettext_* tablice dupliciranih redaka. Ove tablice sadrže prijevode za teme i nizove dodataka.','Remove duplicate rows for dictionary strings'=>'Uklanjanje dupliciranih redaka za nizove rječnika','Cleans up all trp_dictionary_* tables of duplicate rows. These tables contain translations for user-inputted strings such as post content, post title, menus etc.'=>'Čisti sve trp_dictionary_* tablice dupliciranih redaka. Ove tablice sadrže prijevode za nizove koje je unio korisnik kao što su sadržaj objave, naslov objave, izbornici itd.','Remove duplicate rows for original dictionary strings'=>'Uklanjanje dupliciranih redaka za izvorne nizove rječnika','Cleans up all trp_original_strings table of duplicate rows. This table contains strings in the default language, without any translation.<br>The trp_original_meta table, which contains meta information that refers to the post parent’s ID, is also regenerated.<br>Such duplicates can appear in exceptional situations of unexpected behavior.'=>'Čisti sve trp_original_strings tablici dupliciranih redaka. Ova tablica sadrži nizove na zadanom jeziku, bez prijevoda. <br>Tablica trp_original_meta, koja sadrži meta informacije koje se odnose na ID roditelja pošte, također se regenerira. <br>Takvi duplikati mogu se pojaviti u iznimnim situacijama neočekivanog ponašanja.','Replace gettext strings that have original ID NULL with the correct original IDs'=>'Zamijenite gettext nizove koji imaju izvorni ID NULL ispravnim izvornim ID-ovima','Fixes an edge case issue where some gettext strings have the original ID incorrectly set to NULL, causing problems in the Translation Editor.<br>This operation corrects the original IDs in the trp_gettext_* tables.<br>Only check this option if you encountered an issue in the Translation Editor where clicking the green pencil did not bring up the gettext string for translation in the left sidebar.<br>Otherwise, please leave this option unchecked because it\'s an intensive operation.'=>'Rješava problem s rubnim velikim slovima zbog kojeg neki gettext nizovi imaju izvorni ID pogrešno postavljen na NULL, što uzrokuje probleme u uređivaču prijevoda. <br>Ova operacija ispravlja izvorne ID-ove u tablicama trp_gettext_*. <br>Ovu opciju označite samo ako ste naišli na problem u uređivaču prijevoda gdje klikom na zelenu olovku nije prikazan gettext niz za prijevod na lijevoj bočnoj traci. <br>U suprotnom, ostavite ovu opciju neoznačenom jer je to intenzivna operacija.','Optimize Database'=>'Optimizirajte bazu podataka','TranslatePress Database Updater'=>'TranslatePress ažuriranje baze podataka','Updating TranslatePress tables. Please leave this window open.'=>'Ažuriranje tablica TranslatePress. Ostavite ovaj prozor otvoren.','Open colour picker'=>'Otvori birač boja','Enabled'=>'Omogućeno','Disabled'=>'Onemogućeno','Write custom CSS here...'=>'Ovdje napišite prilagođeni CSS...','Include'=>'Obuhvaća','Exclude'=>'Izostavi','Content Restriction Mode'=>'Način ograničenja sadržaja','No languages selected'=>'Nema odabranih jezika','Saving...'=>'Spremanje...','Saved!'=>'Spremljeno!','Save changes'=>'Spremi promjene','Revert to last saved values'=>'Vrati na posljednje spremljene vrijednosti','Revert changes'=>'Vrati promjene','Restoring will revert to the last saved version and discard your current edits.'=>'Vraćanje vratit će na posljednju spremljenu verziju i odbaciti vaše trenutne izmjene.','Revert'=>'Vrati','Keep editing'=>'Nastavi uređivati','Are you sure you want to apply the <strong>%s</strong> preset?'=>'Jeste li sigurni da želite primijeniti <strong>%s</strong> predložak?','It will override your current settings.'=>'To će prepisati vaše trenutne postavke.','Apply preset'=>'Primijeni predložak','Apply %s preset'=>'Primijeni %s predložak','Save failed'=>'Spremanje nije uspjelo','English'=>'Engleski','Spanish'=>'Španjolski','French'=>'Francuski','Minimal Light'=>'Minimalna svijetla','Dark Overlay'=>'Tamni prekrivač','Brand Blue'=>'Plava boja brenda','Bordered'=>'Obrubljena','Popup Preview'=>'Pretpregled skočnog prozora','User Language Detection Method'=>'Metoda otkrivanja korisničkog jezika','Notification Behavior'=>'Ponašanje obavijesti','Popup Content'=>'Sadržaj skočnog prozora','Apply a preset'=>'Primijeni predložak','Customize Design'=>'Prilagodi dizajn','Language detection'=>'Otkrivanje jezika','Select how the language should be detected for first time visitors.<br>The visitor\'s last displayed language will be remembered through cookies.'=>'Odaberite kako će se jezik otkriti za posjetitelje koji prvi put dolaze.<br>Posljednji prikazani jezik posjetitelja bit će zapamćen putem kolačića.','Popup display'=>'Prikaz skočnog prozora','Conditionally display popup based on language'=>'Uvjetno prikaži skočni prozor na temelju jezika','Popup Type'=>'Vrsta skočnog prozora','Visitors will be redirected directly when a different preferred language is detected.'=>'Posjetitelji će biti izravno preusmjereni kada se otkrije drugi preferirani jezik.','Popup Text'=>'Skočni tekst','Button Text'=>'Tekst gumba','Close Button Text'=>'Tekst gumba za zatvaranje','Background color'=>'Boja pozadine','Text color'=>'Boja teksta','Button background color'=>'Boja pozadine gumba','Button hover color'=>'Boja gumba pri najezdu','Button text color'=>'Boja teksta gumba','Button border radius'=>'Radijus obruba gumba','Close icon color'=>'Boja ikone za zatvaranje','Overlay color'=>'Boja prekrivanja','Entrance animation'=>'Ulazna animacija','Animation'=>'Animacija','Fade'=>'Blijedjenje','Slide from top'=>'Klizanje s vrha','Slide from right'=>'Klizanje s desna','Slide from bottom'=>'Klizanje s dna','Slide from left'=>'Klizanje s lijeva','Enable custom CSS'=>'Omogući prilagođeni CSS','No names'=>'Bez imena','Show flags'=>'Prikaži zastave','Rectangle (4:3)'=>'Pravokutnik (4:3)','Square (1:1)'=>'Kvadrat (1:1)','Flag border radius'=>'Radijus obruba zastave','Switcher background'=>'Pozadina prebacivača','Switcher hover background'=>'Pozadina prebacivača na hover','Switcher text'=>'Tekst prebacivača','Switcher hover text'=>'Tekst prebacivača na hover','Switcher border'=>'Rub prebacivača','Switcher border width'=>'Širina obruba prebacivača','Switcher border radius'=>'Polumjer obruba prebacivača','Hover over the language switcher to see it in action!'=>'Pređite mišem preko mjenjača jezika da biste ga vidjeli u akciji!','Switcher Preview'=>'Pretpregled prebacivača','Enable Floating Switcher'=>'Omogući plutajući prebacivač','Switcher is enabled'=>'Prebacivač je omogućen','Switcher is disabled'=>'Prebacivač je onemogućen','Switcher Type'=>'Vrsta prebacivača','Show languages as dropdown'=>'Prikaži jezike kao padajući izbornik','Show languages side by side'=>'Prikaži jezike jedan pokraj drugog','Background hover color'=>'Boja pozadine pri prelasku','Text hover color'=>'Boja teksta pri prelasku','Switcher border color'=>'Boja obruba prebacivača','Flag and text size'=>'Veličina zastave i teksta','Flag icons shape'=>'Oblik ikona zastava','Flag icons border radius'=>'Polumjer obruba ikona zastava','Customize Layout'=>'Prilagodi izgled','Show the small Powered by TranslatePress label in the language switcher.'=>'Prikaži malu oznaku Powered by TranslatePress u prebacivaču jezika.','You have unsaved changes. Leave anyway?'=>'Imate nespremljene promjene. Napustiti svejedno?','Switcher animations'=>'Animacije prebacivača','Transforms the language switcher into a button showing the other available language, not the current one. <br> Only works when there are exactly two languages, the default one and a translation one.'=>'Pretvara prebacivač jezika u gumb koji prikazuje drugi dostupni jezik, a ne trenutni. <br> Djeluje samo kada postoje točno dva jezika, zadani i prijevodni jezik.','This option only works when exactly two languages are published.'=>'Ova opcija djeluje samo kada su objavljena točno dva jezika.','Copied!'=>'Kopirano!','Copy'=>'Kopiraj','Use shortcode on any page or widget. You can also add the Language Switcher Block in the WP Gutenberg Editor.'=>'Koristite shortcode na bilo kojoj stranici ili widgetu. Također možete dodati blok prebacivača jezika u WP Gutenberg uređivaču.','Shortcode'=>'Shortcode','Additional Settings'=>'Dodatne postavke','Open the language switcher shortcode by clicking on it instead of hovering. <br> Close it by clicking on it, anywhere else on the screen or by pressing the escape key. <br> This will affect only the shortcode language switcher.'=>'Otvorite prebacivač jezika u shortcodeu klikom umjesto prelaskom mišem. <br> Zatvorite ga klikom na njega, bilo gdje drugdje na zaslonu ili pritiskom tipke Escape. <br> Ovo utječe samo na prebacivač jezika u shortcodeu.','Menu Switcher Layout'=>'Izgled prebacivača u izborniku','Go to <a href="/wp-admin/nav-menus.php">Appearance → Menus</a> to add languages to the Language Switcher in any menu.<br> <a href="https://translatepress.com/docs/settings/language-switcher/?utm_source=tp-language-switcher&utm_medium=client-site&utm_campaign=ls-menu-item#menu-switcher" target="_blank">Learn more in our documentation.</a>'=>'Idite na <a href="/wp-admin/nav-menus.php">Izgled → Izbornici</a> da biste dodali jezike u prebacivač jezika u bilo kojem izborniku.<br> <a href="https://translatepress.com/docs/settings/language-switcher/?utm_source=tp-language-switcher&utm_medium=client-site&utm_campaign=ls-menu-item#menu-switcher" target="_blank">Saznajte više u našoj dokumentaciji.</a>','Choose in which languages to show the block.'=>'Odaberite na kojim jezicima želite prikazati blok.','Choose from which languages the block is excluded.'=>'Odaberite s kojih jezika je blokiranje isključeno.','Select language(s)'=>'Odaberite jezik(e)','TranslatePress Language Restriction'=>'Ograničenje jezika TranslatePress','Language restrictions cannot be saved on a top-level Classic block. Convert it to blocks or place it inside a Group block first.'=>'Ograničenja jezika ne mogu se spremiti na Klasičnom bloku na najvišoj razini. Pretvorite ga u blokove ili ga prvo stavite